window.JAPAN_STUDY_N5_BOOK={"title":"THÀNH PHỐ KHÔNG ĐƯỢC QUÊN","subtitle":"Tiểu thuyết trí nhớ tiếng Nhật N5","totalPages":94,"chapters":[{"num":1,"page":6,"title":"Cổng sắt bán cả bầu trời","from":1,"to":19},{"num":2,"page":9,"title":"Siêu thị của những chiếc nhãn","from":20,"to":43},{"num":3,"page":12,"title":"Rạp chiếu phim nuốt mất màu","from":44,"to":64},{"num":4,"page":16,"title":"Ngày hôm qua chạy trốn","from":65,"to":88},{"num":5,"page":19,"title":"Cuộc thi tài năng của những","from":89,"to":109},{"num":6,"page":22,"title":"Lớp học phép thuật và cây bút","from":110,"to":134},{"num":7,"page":25,"title":"Trạm kiểm soát của người gác","from":135,"to":155},{"num":8,"page":28,"title":"Công viên mọc ra từ một tấm","from":156,"to":175},{"num":9,"page":31,"title":"Ngã tư nơi thời tiết biết suy","from":176,"to":195},{"num":10,"page":34,"title":"Bệnh viện chữa những vết","from":196,"to":216},{"num":11,"page":37,"title":"Nhà máy tăng ca tới ngày tận","from":217,"to":236},{"num":12,"page":41,"title":"Kho chứa những thứ có và","from":237,"to":257},{"num":13,"page":44,"title":"Chuyến tàu chạy xuyên qua","from":258,"to":278},{"num":14,"page":47,"title":"Bữa tối của hai mươi mốt vị","from":279,"to":299},{"num":15,"page":50,"title":"Tháp đồng hồ ăn mất thứ Hai","from":300,"to":320},{"num":16,"page":53,"title":"Bưu điện gửi thư đến ngày mai","from":321,"to":340},{"num":17,"page":57,"title":"Thám tử của mười hai câu hỏi","from":341,"to":361},{"num":18,"page":60,"title":"Ngôi chợ bán những thứ","from":362,"to":382},{"num":19,"page":64,"title":"Tiệm quà nơi lòng tốt có hình","from":383,"to":403},{"num":20,"page":67,"title":"Hồ điều ước và đám cưới trên","from":404,"to":423},{"num":21,"page":70,"title":"Phòng khám của những lời","from":424,"to":443},{"num":22,"page":73,"title":"Phố mặt nạ và những tên gọi","from":444,"to":463},{"num":23,"page":77,"title":"Xưởng tranh giữ lại tiếng hát","from":464,"to":484},{"num":24,"page":80,"title":"Đài truyền hình phát toàn tin","from":485,"to":508},{"num":25,"page":83,"title":"Xưởng sửa chữa thành phố","from":509,"to":528},{"num":26,"page":86,"title":"Đường đua cuối cùng: không ai","from":529,"to":545}],"pages":["","LỜI MỞ\n\n\n\n\nLá thư không có người gửi\n“Có những nơi chỉ tồn tại khi ta còn biết gọi tên chúng.”\n\n\nVào đêm trước khi thành phố biến mất, An thấy một con mèo đen\nngồi trên trang giấy trắng. Nó tự giới thiệu là Mực, người canh giữ\nnhững âm thanh cuối cùng còn sót lại ở nơi mang tên Ký Ức.\n\n“Những từ ngữ ở đây đều có hình dạng,” Mực bảo. “Từ cao có thể\ndựng thành cột xuyên mây; từ lạnh có thể biến hòm thư thành bão\ntuyết. Muốn vượt qua, cậu phải nhìn thấy cảnh tượng ấy và gọi\nđược tiếng Nhật của nó.”\n\nTrong truyện, những chữ xanh là phù hiệu tiếng Nhật kèm cách\nđọc. Nghĩa tiếng Việt được đặt ngay cạnh, như lời dịch mà An nghe\nthấy. Hãy đọc cuốn sách như một cuộc phiêu lưu: mỗi cảnh là một\ndấu ấn ở một địa điểm cố định, và các chương nối với nhau thành\nmột đường đi duy nhất.\n\nMột tiếng Nhật có thể tái xuất như một nhân vật cũ. Cả 545 mục từ\ntài liệu gốc đều có mặt trên hành trình, kể cả những lần lặp.\n\nTừ vựng theo TỪ VỰNG N5.pdf đã cung cấp (mục 001–545); tình tiết\ntruyện là sáng tác mới.\n\n\n\n\n                                 2","S Á C H G Ồ M S Á U TẬ P\n\n\n\n\nMục lục của thành phố\nTẬP I — BẢN ĐỒ CỦA NHỮNG CẢM GIÁC\n01       Cổng sắt bán cả bầu trời (1–19)\n02       Siêu thị của những chiếc nhãn biết cãi nhau (20–43)\n03       Rạp chiếu phim nuốt mất màu sắc (44–64)\n\n\nTẬP II — THÀNH PHỐ KHÔNG NGỦ\n04       Ngày hôm qua chạy trốn (65–88)\n05       Cuộc thi tài năng của những người không có khả năng (89–109)\n06       Lớp học phép thuật và cây bút không trả (110–134)\n07       Trạm kiểm soát của người gác cổng vô hình (135–155)\n08       Công viên mọc ra từ một tấm bưu thiếp (156–175)\n09       Ngã tư nơi thời tiết biết suy nghĩ (176–195)\n10       Bệnh viện chữa những vết thương của trí nhớ (196–216)\n11       Nhà máy tăng ca tới ngày tận thế (217–236)\n\n\nTẬP III — THẾ GIỚI CÓ HÌNH DÁNG\n12       Kho chứa những thứ có và không có (237–257)\n13       Chuyến tàu chạy xuyên qua bản đồ (258–278)\n14       Bữa tối của hai mươi mốt vị khách (279–299)\n15       Tháp đồng hồ ăn mất thứ Hai (300–320)\n\n\n\n                                   3","16   Bưu điện gửi thư đến ngày mai (321–340)\n\n\nTẬP IV — CHIẾC CHÌA KHÓA LÀ MỘT CÂU HỎI\n17   Thám tử của mười hai câu hỏi (341–361)\n18   Ngôi chợ bán những thứ không ai nhìn thấy (362–382)\n\n\nTẬP V — ĐIỀU MÌNH MUỐN GIỮ LẠI\n19   Tiệm quà nơi lòng tốt có hình dạng (383–403)\n20   Hồ điều ước và đám cưới trên mây (404–423)\n21   Phòng khám của những lời hứa (424–443)\n22   Phố mặt nạ và những tên gọi thân thương (444–463)\n\n\nTẬP VI — TIẾNG CHUÔNG CUỐI CÙNG\n23   Xưởng tranh giữ lại tiếng hát (464–484)\n24   Đài truyền hình phát toàn tin giả (485–508)\n25   Xưởng sửa chữa thành phố (509–528)\n26   Đường đua cuối cùng: không ai bị lãng quên (529–545)\n\n\n\n\n                              4","TẬ P I • 6 TẬ P • 2 6 C H Ư Ơ N G\n\n\n\n\nBẢN ĐỒ CỦA\nNHỮNG CẢM GIÁC\nTính chất biến thành màu sắc, độ cao, tiếng cười\nvà bóng tối.\n\n\n\n\n                     一","TẬ P I    /   CHƯƠNG 01   /   PHÙ HIỆU 001–019\n\n\n\nCổng sắt bán cả bầu trời\n   Thành phố mang tên Ký Ức biến mất khỏi mọi tấm bản đồ vào\n   đúng nửa đêm. An đi tìm em gái thất lạc, chỉ đem theo một\n   cuốn sổ trắng; bất ngờ, con mèo đen tên Mực lên tiếng: “Muốn\n   vào thành phố, phải gọi đúng tên của những điều đang xảy\n   ra.”\n\nCổng thành mở ra như một cái miệng khổng lồ. Nhưng mỗi bước\nchân của An lại khiến thế giới biến dạng; cô nhận ra ở đây, một\nchữ Nhật phát sáng có thể điều khiển cả cảnh vật.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Ở cổng sắt, cột\nvàng cao xuyên mây, giá dán 1 tỷ yên. Mực kêu lên một tiếng; trên\nnền nhà xuất hiện 高い（たかい） — Cao; đắt. Họ vừa đến chuông\ncửa thì mưa nhãn giảm giá 1 yên rơi như tuyết. An thử đọc phù\nhiệu 安い（やすい） — Rẻ, giá thấp và cảnh tượng đứng yên. Ngay\nbên hòm thư, cơn bão tuyết khiến răng mọi người va lập cập. Ánh\nsáng rót thành ký tự 寒い（さむい） — Lạnh, rét như đang chỉ\nđường. Có tiếng răng rắc dưới lối lát gạch: mặt trời tí hon dí sát\nmặt làm không khí nóng rực. Mực dùng đuôi vẽ lên bóng tối\n暑い（あつい） — Nóng, oi nóng.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Khi ngang qua luống hoa, con\nmèo diễn hài khiến bông hoa cười lăn. Những nét mực tự sắp\nthành 面白い（おもしろい） — Thú vị, hay; buồn cười; An lập tức ghi\nnhớ cảnh ấy. Không kịp gọi Mực, An thấy ở thảm cỏ ổ khóa có 999\n\n\n                                   6","tầng, giải mã mãi không xong. Tiếng Nhật vang lên từ chính vật ấy:\n難しい（むずかしい） — Khó. Dưới ánh đèn nơi cây táo, cánh cửa\nmới toanh còn bọc ni-lông lấp lánh. Một dòng chữ khác phát sáng:\n新しい（あたらしい） — Mới. Còn tại ghế đá, đôi giày khổng lồ to\nbằng tòa nhà. An thì thầm phù hiệu 大きい（おおきい） — To, lớn,\nnghe nó hòa vào tiếng tim mình.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Ở hòn non bộ, đôi giày tí hon chỉ\nbằng hạt gạo. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n小さい（ちいさい） — Nhỏ, bé. Họ vừa đến cầu gỗ thì sàn nhảy bùng\nsáng, mọi người vui vẻ tung hô. An thử đọc phù hiệu\n楽しい（たのしい） — Vui, vui vẻ, thú vị và cảnh tượng đứng yên.\nNgay bên võng, tủ lạnh nằm võng, ngáp vì quá rảnh. Ánh sáng rót\nthành ký tự 暇（ひま） — Rảnh, rảnh rỗi như đang chỉ đường. Có\ntiếng răng rắc dưới hồ cá: mọi tiếng động biến mất, cô thủ thư giơ\ntay ra hiệu im lặng. Mực dùng đuôi vẽ lên bóng tối 静か（しずか）\n— Yên tĩnh, yên lặng.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Khi ngang qua đài phun nước,\nrobot 100 tay tự làm hết mọi việc rất tiện. Những nét mực tự sắp\nthành 便利（べんり） — Tiện lợi, thuận tiện; An lập tức ghi nhớ cảnh\nấy. Không kịp gọi Mực, An thấy ở chậu bonsai người tí hon tử tế cúi\nxuống giúp từng con kiến. Tiếng Nhật vang lên từ chính vật ấy:\n親切（しんせつ） — Tốt bụng, tử tế, nhiệt tình. Dưới ánh đèn nơi bàn\ntrà, món ăn yêu thích phun hàng ngàn trái tim. Một dòng chữ khác\nphát sáng: 好き（すき） — Thích, yêu thích. Còn tại xích đu, đĩa thức\năn đáng ghét đuổi theo khiến bà nhăn mặt. An thì thầm phù hiệu\n嫌い（きらい） — Ghét, không thích, nghe nó hòa vào tiếng tim mình.\n\n\n\n\n                                  7","Tiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Ở bậc thềm, cầu thang\ndốc như Everest, leo rất vất vả. Mực kêu lên một tiếng; trên nền\nnhà xuất hiện 大変（たいへん） — Vất vả, khó khăn; nghiêm trọng. Họ\nvừa đến cửa hiên thì lễ hội trống rộn ràng, người chen kín lối. An\nthử đọc phù hiệu 賑やか（にぎやか） — Náo nhiệt, nhộn nhịp và cảnh\ntượng đứng yên. Ngay bên tượng đá, cánh cửa siêu bền bị búa đập\nmà không hề xước. Ánh sáng rót thành ký tự 丈夫（じょうぶ） —\nKhỏe mạnh; bền, chắc như đang chỉ đường.\n\n  Sau cánh cửa bền chắc cuối cùng, một mảnh pha lê rơi vào tay\n  An. Mực bảo: “Mới chỉ là vết nứt đầu tiên. Thành phố còn giấu\n  những từ mạnh hơn.”\n\n\n\n\n                                8","TẬ P I   /   CHƯƠNG 02   /   PHÙ HIỆU 020–043\n\n\n\nSiêu thị của những chiếc nhãn\nbiết cãi nhau\n   Sáng hôm sau, Mực dẫn An vào siêu thị mà cửa xoay chỉ chịu\n   quay ngược. Ông chủ vô hình hứa sẽ trả lại trí nhớ cho người\n   đi hết dãy hàng mà không lẫn lộn hai nghĩa đối lập.\n\nAn cố nhìn từng đồ vật như một nhân chứng. Mỗi quầy phát ra\nmột phép biến hóa ngược đời: thứ đắt thành rẻ, thứ yên tĩnh hóa\nnáo nhiệt; chẳng có món hàng nào chịu nằm yên.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Chạm vào cửa\nxoay, An bỗng nhìn thấy một cột giá cao 1 tỷ yên vọt lên trời, nối\ncổng khu trước. Dòng chữ 高い（たかい） — Cao; đắt hiện ra giữa\nkhông khí. Ở bảng khuyến mãi, biển rẻ 1 yên bay xuyên cửa, nối\ncơn mưa giá rẻ. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n安い（やすい） — Rẻ. Họ vừa đến quầy thông tin thì chiếc ghế lùn tịt\nchỉ cao bằng mắt cá chân. An thử đọc phù hiệu 低い（ひくい） —\nThấp và cảnh tượng đứng yên. Ngay bên giỏ hàng, hoa và sàn nhà\nđược kỳ cọ sạch đẹp sáng như gương. Ánh sáng rót thành ký tự\nきれい「な」（きれい） — Đẹp; sạch sẽ như đang chỉ đường. Có tiếng\nrăng rắc dưới cửa kính: một người nổi tiếng bước xuống thảm đỏ,\nfan hét tên. Mực dùng đuôi vẽ lên bóng tối 有名「な」（ゆうめい）\n— Nổi tiếng.\n\n\n\n\n                                  9","Chiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Khi ngang qua kệ gia vị, thành\nphố đang ồn bỗng im phăng phắc như thư viện. Những nét mực tự\nsắp thành 静か「な」（しずか） — Yên tĩnh; An lập tức ghi nhớ cảnh\nấy. Không kịp gọi Mực, An thấy ở kệ rau lễ hội pháo hoa làm cả con\nphố   náo   nhiệt.   Tiếng   Nhật    vang   lên   từ   chính   vật   ấy:\n賑やか「な」（にぎやか） — Náo nhiệt, nhộn nhịp. Dưới ánh đèn nơi\nkệ hoa, máy robot đưa mọi thứ đến tận tay thật tiện lợi. Một dòng\nchữ khác phát sáng: 便利「な」（べんり） — Tiện lợi, thuận tiện. Còn\ntại máy bán nước, một con đường cụt khiến ai cũng đi vòng rất bất\ntiện. An thì thầm phù hiệu 不便「な」（ふべん） — Bất tiện, nghe nó\nhòa vào tiếng tim mình. Chạm vào quầy bánh, An bỗng nhìn thấy\nvận động viên xanh khỏe nhảy bật qua trần nhà. Dòng chữ\n元気「な」（げんき） — Khỏe mạnh, khỏe khoắn; năng động hiện ra\ngiữa không khí.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Họ vừa đến bàn ăn thử thì một\ncon lười rảnh rỗi ngủ giữa biển lịch trống. An thử đọc phù hiệu\n暇「な」（ひま） — Rảnh, rảnh rỗi và cảnh tượng đứng yên. Ngay\nbên kệ đồ bếp, chiếc túi đẹp tuyệt vời phát ra hào quang lấp lánh.\nÁnh sáng rót thành ký tự 素敵「な」（すてき） — Tuyệt vời, đẹp,\nđáng yêu như đang chỉ đường. Có tiếng răng rắc dưới quầy chăm\nsóc: đầu bếp tung món ăn lên trời và nấu như xiếc. Mực dùng đuôi\nvẽ lên bóng tối 料理（りょうり） — Món ăn; nấu ăn. Tiến thêm một\nbước đến quầy gương, An bắt gặp một thị trấn tí hon mọc lên từ\nkhe gạch. Phù hiệu vừa thức dậy mang tên 町（まち） — Thị trấn,\nphố, khu phố. Khi ngang qua kệ sách, ngọn núi mọc thẳng lên chọc\nthủng mái nhà. Những nét mực tự sắp thành 山（やま） — Núi; An\nlập tức ghi nhớ cảnh ấy.\n\n\n\n\n                                    10","An biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Dưới ánh đèn nơi kho hàng,\nmột dấu X đỏ chỉ vào chỗ bí mật phải tìm. Một dòng chữ khác phát\nsáng: 所（ところ） — Nơi, chỗ. Còn tại sàn lát gạch, ký túc xá công ty\nnhét 100 chiếc giường vào một hộp. An thì thầm phù hiệu\n寮（りょう） — Ký túc xá, nghe nó hòa vào tiếng tim mình. Chạm\nvào thang cuốn, An bỗng nhìn thấy nhà hàng di động chạy bằng\nchân bàn. Dòng chữ レストラン（レストラン） — Nhà hàng hiện ra\ngiữa không khí. Ở biển chỉ đường, một huy chương vàng số 1 to\nhơn núi. Mực kêu lên một tiếng; trên nền nhà xuất hiện\nいちばん（いちばん） — Nhất. Họ vừa đến tủ đông thì hai người\nchạy, người sau bỗng vượt hơn hẳn 100 mét. An thử đọc phù hiệu\nずっと（ずっと） — Hơn hẳn, ... nhiều hơn và cảnh tượng đứng yên.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Có tiếng răng rắc dưới\nmáy tính tiền: hai cánh cửa hỏi bên nào, một cửa phun khói. Mực\ndùng đuôi vẽ lên bóng tối どちら（どちら） — Cái nào, bên nào. Tiến\nthêm một bước đến băng chuyền, An bắt gặp nhiệt kế leo khá cao\nnhưng chưa đến đỉnh. Phù hiệu vừa thức dậy mang tên\nかなり（かなり） — Khá, khá là, tương đối. Khi ngang qua túi mua\nsắm, chiếc giỏ nở to hơn nữa mỗi lần chớp mắt. Những nét mực tự\nsắp thành もっと（もっと） — Hơn nữa, thêm nữa; An lập tức ghi nhớ\ncảnh ấy. Không kịp gọi Mực, An thấy ở cửa ra băng chuyền chạy\nsuốt đêm không chịu dừng. Tiếng Nhật vang lên từ chính vật ấy:\nずっと（ずっと） — Hơn hẳn; suốt, liên tục.\n\n  Cuối băng chuyền, một chiếc túi trống vẫn chạy mãi. An hiểu\n  rằng từ có thể lặp lại nhưng ý nghĩa phụ thuộc cảnh mình nhìn\n  thấy; cô cất điều ấy vào sổ.\n\n\n\n\n                                 11","TẬ P I   /   CHƯƠNG 03   /   PHÙ HIỆU 044–064\n\n\n\nRạp chiếu phim nuốt mất màu\nsắc\n   Rạp chiếu bỏ hoang hiện lên giữa khu phố. Trên vé chỉ có\n   dòng chữ: “Tìm lại bảy màu của bầu trời, rồi người bị xóa tên\n   sẽ hiện hình.” An mua vé bằng chính tiếng cười của mình.\n\nBên trong, màn ảnh không chiếu phim mà thay đổi trọng lượng,\nkích thước, vị giác và cả thời tiết của khán giả. Mực phải cắn vạt áo\nAn để giữ cô khỏi bị cuốn vào những cảnh phim.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Có tiếng răng rắc\ndưới biển tên rạp: bóng đèn biến thành mặt trời sáng rực như ban\nngày. Mực dùng đuôi vẽ lên bóng tối 明るい（あかるい） — Sáng,\nsáng sủa; vui vẻ. Tiến thêm một bước đến áp phích phim, An bắt\ngặp mực đen nuốt sạch ánh sáng khiến mọi thứ tối om. Phù hiệu\nvừa thức dậy mang tên 暗い（くらい） — Tối, tối tăm; u ám. Khi\nngang qua cửa bán vé, con rắn dài bất tận quấn quanh toàn bộ\nrạp. Những nét mực tự sắp thành 長い（ながい） — Dài, lâu; An lập\ntức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở hàng người chờ\nchiếc thước ngắn 1 milimét chặn ngang lối đi. Tiếng Nhật vang lên\ntừ chính vật ấy: 短い（みじかい） — Ngắn.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Còn tại máy quét vé, quả tạ\nnặng như núi rơi làm sàn rung chuyển. An thì thầm phù hiệu\n重い（おもい） — Nặng, nghe nó hòa vào tiếng tim mình. Chạm vào\n\n\n\n                                 12","thảm đỏ, An bỗng nhìn thấy lông chim nhẹ bay lơ lửng trên đầu\nmọi người. Dòng chữ 軽い（かるい） — Nhẹ hiện ra giữa không khí.\nỞ tủ kính, căn phòng giãn rộng thành sân bóng khổng lồ. Mực kêu\nlên một tiếng; trên nền nhà xuất hiện 広い（ひろい） — Rộng, rộng\nrãi. Họ vừa đến quầy bỏng ngô thì các bức tường ép lại chật đến\nmức không cử động được. An thử đọc phù hiệu 狭い（せまい） —\nHẹp, chật và cảnh tượng đứng yên.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Có tiếng răng rắc dưới quầy nước:\nsuối si-rô ngọt ngào làm ai cũng dính chặt. Mực dùng đuôi vẽ lên\nbóng tối 甘い（あまい） — Ngọt. Tiến thêm một bước đến cửa phòng\nchiếu, An bắt gặp núi ớt đỏ phun lửa cay xè vào bắp rang. Phù\nhiệu vừa thức dậy mang tên 辛い（からい） — Cay. Khi ngang qua\nhàng ghế đầu, cà phê đắng làm mặt người uống méo thành hình\nvuông. Những nét mực tự sắp thành 苦い（にがい） — Đắng; An lập\ntức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở tay vịn bát mì\nnóng bỏng bốc khói như núi lửa. Tiếng Nhật vang lên từ chính vật\nấy: 熱い（あつい） — Nóng (đồ vật, thức ăn, đồ uống...).\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Còn tại trần rạp, cốc nước đá\nlạnh chạm vào là tê cả tay. An thì thầm phù hiệu 冷たい（つめたい）\n— Lạnh (đồ vật, nước...), nghe nó hòa vào tiếng tim mình. Chạm vào\nđèn chiếu, An bỗng nhìn thấy nghệ sĩ nhận cúp vàng vì quá giỏi.\nDòng chữ 上手「な」（じょうず） — Giỏi, khéo hiện ra giữa không\nkhí. Ở màn chiếu, ca sĩ hát dở đến mức micro chảy nước mắt. Mực\nkêu lên một tiếng; trên nền nhà xuất hiện 下手「な」（へた） —\nKém, dở, không giỏi. Họ vừa đến màn nhung thì cơn mưa bông tuyết\ntrắng phủ hết khán đài. An thử đọc phù hiệu 白い（しろい） —\nTrắng và cảnh tượng đứng yên.\n\n\n\n                                13","Tiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Có tiếng răng rắc dưới\nloa trái: mực đen chảy từ màn chiếu xuống như thác. Mực dùng\nđuôi vẽ lên bóng tối 黒い（くろい） — Đen. Tiến thêm một bước đến\nloa phải, An bắt gặp quả táo đỏ khổng lồ nổ tung thành giấy đỏ.\nPhù hiệu vừa thức dậy mang tên 赤い（あかい） — Đỏ. Khi ngang\nqua lối thoát hiểm, bầu trời xanh tràn khỏi màn chiếu ra cả rạp.\nNhững nét mực tự sắp thành 青い（あおい） — Xanh, xanh da trời;\nAn lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở cửa hậu\ntrường con sâu biến thành bướm ngay trước mắt. Tiếng Nhật vang\nlên từ chính vật ấy: なります（なります） — Trở nên, trở thành.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Còn tại tượng oscar, một chiếc nút\nbấm làm cả căn phòng đổi màu. An thì thầm phù hiệu\nします（します） — Làm; làm cho trở thành..., nghe nó hòa vào tiếng\ntim mình.\n\n  Khi ánh sáng cuối cùng bừng lên, An nhìn thấy bóng em gái\n  trong màn chiếu. Một cánh cửa ghi “Hành Động” mở ra; họ lập\n  tức chạy theo.\n\n\n\n\n                               14","TẬ P I I • 6 TẬ P • 2 6 C H Ư Ơ N G\n\n\n\n\nTHÀNH PHỐ\nKHÔNG NGỦ\nMỗi hành động là một cánh cửa; sai một nhịp,\ncả ngày sẽ bị khóa.\n\n\n\n\n                      二","TẬ P I I   /   CHƯƠNG 04   /   PHÙ HIỆU 065–088\n\n\n\nNgày hôm qua chạy trốn\n   Phố thứ hai chỉ có ba ngày: hôm qua, hôm nay và ngày mai.\n   Một bà cụ bán đồng hồ nói rằng nếu An không sắp lại những\n   hành động của một ngày, cả thành phố sẽ mắc kẹt trong một\n   buổi sáng kéo dài vô tận.\n\nAn bước vào một căn nhà nơi tất cả đồ vật đều hành động trước\ncon người. Tivi nhìn chủ nhà, sách tự đọc, giường tự hát. Để thoát\nra, cô phải đi theo nhịp thức dậy, làm việc rồi ngủ.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Tiến thêm một\nbước đến cổng nhà, An bắt gặp một người đi qua cổng rồi biến mất\nsau mây. Phù hiệu vừa thức dậy mang tên 行きます（いきます） —\nĐi. Khi ngang qua móc chìa khóa, người bạn từ trời rơi xuống kêu\nta đến rồi. Những nét mực tự sắp thành 来ます（きます） — Đến; An\nlập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở bệ giày\nchiếc thảm bay đưa mọi người trở về nhà. Tiếng Nhật vang lên từ\nchính vật ấy: 帰ります（かえります） — Về, trở về. Dưới ánh đèn nơi\nhành lang, nồi cơm tự nhảy vào miệng mọi người. Một dòng chữ\nkhác phát sáng: 食べます（たべます） — Ăn. Còn tại cửa bếp, cốc\nnước biết đi bắt ai cũng phải uống. An thì thầm phù hiệu\n飲みます（のみます） — Uống, nghe nó hòa vào tiếng tim mình.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Ở bát cơm, chiếc tivi mọc đôi\nmắt khổng lồ nhìn quanh. Mực kêu lên một tiếng; trên nền nhà\nxuất hiện 見ます（みます） — Xem, nhìn. Họ vừa đến ly nước thì loa\n\n\n                                   16","mọc tai nghe được cả tiếng thì thầm và hỏi lại. An thử đọc phù\nhiệu 聞きます（ききます） — Nghe; hỏi và cảnh tượng đứng yên.\nNgay bên tivi, cuốn sách tự lật trang và đọc thành tiếng. Ánh sáng\nrót thành ký tự 読みます（よみます） — Đọc như đang chỉ đường. Có\ntiếng răng rắc dưới tai nghe: chiếc bút máy tự viết kín cả trần nhà.\nMực dùng đuôi vẽ lên bóng tối 書きます（かきます） — Viết. Tiến\nthêm một bước đến kệ sách, An bắt gặp mười bàn tay robot đồng\nloạt làm việc. Phù hiệu vừa thức dậy mang tên します（します） —\nLàm.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Không kịp gọi Mực, An thấy ở bàn\nviết chiếc giường hát ru khiến ai cũng ngủ ngay. Tiếng Nhật vang\nlên từ chính vật ấy: 寝ます（ねます） — Ngủ, đi ngủ. Dưới ánh đèn\nnơi giường ngủ, đồng hồ báo thức nổ như pháo làm mọi người bật\ndậy. Một dòng chữ khác phát sáng: 起きます（おきます） — Thức\ndậy. Còn tại đồng hồ báo thức, hôm nay đóng dấu đỏ lên toàn bộ tờ\nlịch. An thì thầm phù hiệu 今日（きょう） — Hôm nay, nghe nó hòa\nvào tiếng tim mình. Chạm vào lịch treo, An bỗng nhìn thấy ngày\nmai từ lịch nhảy ra như người máy tương lai. Dòng chữ\n明日（あした） — Ngày mai hiện ra giữa không khí. Ở cửa sổ, hôm\nqua đội mũ cũ lùi ngược khỏi tờ lịch. Mực kêu lên một tiếng; trên\nnền nhà xuất hiện 昨日（きのう） — Hôm qua.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Ngay bên bàn ăn, mỗi ngày một\ncon gà trống nhảy lên cùng giờ. Ánh sáng rót thành ký tự\n毎日（まいにち） — Mỗi ngày, hằng ngày như đang chỉ đường. Có\ntiếng răng rắc dưới ấm trà: mặt trời buổi sáng mang tách cà phê\ntới. Mực dùng đuôi vẽ lên bóng tối 朝（あさ） — Buổi sáng. Tiến\nthêm một bước đến thùng báo, An bắt gặp mặt trời buổi trưa ngồi\n\n\n\n                                 17","ăn cơm thật lớn. Phù hiệu vừa thức dậy mang tên 昼（ひる） — Buổi\ntrưa, ban ngày. Khi ngang qua tủ sách, mặt trăng buổi tối đội mũ\nngủ màu tím. Những nét mực tự sắp thành 晩（ばん） — Buổi tối,\ntối; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở cửa\nnhà tắm hạt cơm phồng lên thành chiếc giường bữa ăn. Tiếng Nhật\nvang lên từ chính vật ấy: ご飯（ごはん） — Cơm; bữa ăn.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Còn tại vòi sen, cốc nước\nđổ ra cả một hồ nước xanh. An thì thầm phù hiệu 水（みず） —\nNước, nghe nó hòa vào tiếng tim mình. Chạm vào tủ lạnh, An bỗng\nnhìn thấy con báo giấy chạy vòng quanh bàn làm việc. Dòng chữ\n新聞（しんぶん） — Báo, tờ báo hiện ra giữa không khí. Ở bàn làm\nviệc, sách mở ra thành chiếc thang lên trời. Mực kêu lên một tiếng;\ntrên nền nhà xuất hiện 本（ほん） — Sách. Họ vừa đến đèn ngủ thì\nmột tờ báo gần đây bay vào cửa sổ. An thử đọc phù hiệu\n最近（さいきん） — Gần đây, dạo gần đây và cảnh tượng đứng yên.\n\n  Qua ô cửa sổ, An nhìn thấy đêm đang trở lại. Cô đã giành lại\n  thời gian, nhưng tiếng hát từ sân khấu bên kia đường đang gọi\n  tên mình.\n\n\n\n\n                                18","TẬ P I I   /   CHƯƠNG 05   /   PHÙ HIỆU 089–109\n\n\n\nCuộc thi tài năng của những\nngười không có khả năng\n   Một ông bầu đeo mặt nạ đòi An biểu diễn một tài năng chưa\n   từng luyện. “Ở đây, chuyện không thể sẽ thành có thể,” ông\n   cười. Mực đáp: “Vậy chúng tôi sẽ biến sân khấu thành lớp\n   học.”\n\nDưới ánh đèn sân khấu, tiếng nhạc bay thành hình, chiếc đàn bỏ\nchạy, hồ bơi mọc giữa ghế khán giả. Những dòng tiếng Nhật lóe lên\ntheo từng màn biểu diễn, buộc An hiểu sự khác nhau giữa nói, hát,\nlàm và hiểu.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Còn tại cổng sân\nkhấu, siêu nhân khoe có thể bay qua sân khấu. An thì thầm phù\nhiệu できます（できます） — Có thể, làm được, nghe nó hòa vào tiếng\ntim mình. Chạm vào đèn neon, An bỗng nhìn thấy ca sĩ phóng nốt\nnhạc khổng lồ ra từ miệng. Dòng chữ 歌います（うたいます） — Hát\nhiện ra giữa không khí. Ở mic đứng, đàn piano bỗng bật chân và\ntự chơi giai điệu. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n弾きます（ひきます） — Chơi, đánh đàn. Họ vừa đến đàn piano thì\nvận động viên bơi giữa không trung như cá. An thử đọc phù hiệu\n泳ぎます（およぎます） — Bơi và cảnh tượng đứng yên.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Có tiếng răng rắc dưới hồ bơi\ngiả: xe ô tô tự lái vòng quanh người xem. Mực dùng đuôi vẽ lên\n\n\n\n                                   19","bóng tối 運転します（うんてんします） — Lái, điều khiển phương tiện.\nTiến thêm một bước đến vô lăng xe, An bắt gặp đầu bếp nấu món\năn từ những tia chớp. Phù hiệu vừa thức dậy mang tên\n料理します（りょうりします） — Nấu ăn. Khi ngang qua bếp diễn,\nmáy in làm ra cả ngôi nhà từ một tờ giấy. Những nét mực tự sắp\nthành 作ります（つくります） — Làm, chế tạo, tạo ra; An lập tức ghi\nnhớ cảnh ấy. Không kịp gọi Mực, An thấy ở bàn thủ công diễn viên\nnói chuyện không ngừng với cái mic. Tiếng Nhật vang lên từ chính\nvật ấy: 話します（はなします） — Nói, nói chuyện.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Còn tại sân khấu trái, một cái\nmiệng nói ra chữ cảm ơn khổng lồ. An thì thầm phù hiệu\n言います（いいます） — Nói, nói rằng, nghe nó hòa vào tiếng tim\nmình. Chạm vào sân khấu phải, An bỗng nhìn thấy máy phiên dịch\nhiểu   cả   ngôn   ngữ   người   ngoài   hành   tinh.   Dòng   chữ\nわかります（わかります） — Hiểu, biết hiện ra giữa không khí. Ở tai\nnghe, lá cờ Nhật biến thành cuốn sách tiếng Nhật. Mực kêu lên một\ntiếng; trên nền nhà xuất hiện 日本語（にほんご） — Tiếng Nhật. Họ\nvừa đến bảng phiên dịch thì bảng tiếng Anh bỗng mọc cánh bay.\nAn thử đọc phù hiệu 英語（えいご） — Tiếng Anh và cảnh tượng\nđứng yên.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Có tiếng răng rắc dưới bức\ntường nhật: bài hát nhảy ra khỏi chiếc đĩa nhạc. Mực dùng đuôi vẽ\nlên bóng tối 歌（うた） — Bài hát. Tiến thêm một bước đến bức\ntường anh, An bắt gặp đàn piano to bằng xe buýt tự chạy trên sân\nkhấu. Phù hiệu vừa thức dậy mang tên ピアノ（ピアノ） — Đàn\npiano. Khi ngang qua máy phát nhạc, guitar dài ba mét gảy ra pháo\nhoa. Những nét mực tự sắp thành ギター（ギター） — Đàn guitar; An\n\n\n\n                                 20","lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở ghế nhạc\ncông mọi dụng cụ thể thao cùng chơi bóng một lúc. Tiếng Nhật\nvang lên từ chính vật ấy: スポーツ（スポーツ） — Thể thao.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Còn tại giá đàn guitar,\nquả bóng tennis to bằng mặt trăng đập xuống đất. An thì thầm phù\nhiệu テニス（テニス） — Tennis, quần vợt, nghe nó hòa vào tiếng tim\nmình. Chạm vào sàn thể thao, An bỗng nhìn thấy ngọn núi trượt\ntuyết mọc giữa sàn diễn. Dòng chữ スキー（スキー） — Trượt tuyết\nhiện ra giữa không khí. Ở sân tennis, đoàn vũ công nhảy tung cả\nsàn gỗ. Mực kêu lên một tiếng; trên nền nhà xuất hiện\nダンス（ダンス） — Nhảy, khiêu vũ. Họ vừa đến đồi tuyết thì mũi tên\nchỉ về phía trước nhưng quay 360 độ. An thử đọc phù hiệu\n前（まえ） — Trước, phía trước và cảnh tượng đứng yên.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Có tiếng răng rắc dưới sàn nhảy:\nmột chữ VIỆC to đùng tự biến thành đồ vật. Mực dùng đuôi vẽ lên\nbóng tối こと（こと） — Việc, chuyện; dùng để danh từ hóa.\n\n  Khán giả vỗ tay. Từ chiếc micro, một mảnh gương màu xanh rơi\n  xuống. Nó phản chiếu ngôi trường phép thuật tiếp theo.\n\n\n\n\n                               21","TẬ P I I   /   CHƯƠNG 06   /   PHÙ HIỆU 110–134\n\n\n\nLớp học phép thuật và cây bút\nkhông trả\n   Trong ngôi trường này, mọi thứ cho mượn đều biết biến mất,\n   còn mọi thứ đi mượn đều đòi về chỗ cũ. Thầy giáo là một cái\n   bảng biết nói và bài thi là tìm lại chiếc chìa khóa của căn\n   phòng bị niêm phong.\n\nAn không thể dùng sức mạnh; cô chỉ có thể hỏi, nghe, nhờ giúp,\ncho xem, đặt, lấy, mở rồi đóng theo đúng thứ tự. Mực cố tình làm\nsai một phép để An nhìn thấy hậu quả rõ ràng.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Chạm vào cửa\nlớp, An bỗng nhìn thấy hành khách chờ tàu đến mức râu dài chạm\nđất. Dòng chữ 待ちます（まちます） — Đợi, chờ hiện ra giữa không\nkhí. Ở chuông trường, chuông lớp gọi tên mọi người liên hồi. Mực\nkêu lên một tiếng; trên nền nhà xuất hiện 呼びます（よびます） —\nGọi. Họ vừa đến bàn giáo viên thì người tí hon phụ giúp khuân cái\nbàn nặng. An thử đọc phù hiệu 手伝います（てつだいます） — Giúp\nđỡ, phụ giúp và cảnh tượng đứng yên. Ngay bên bảng phấn, giáo\nviên dạy khiến chữ Nhật nhảy múa. Ánh sáng rót thành ký tự\n教えます（おしえます） — Dạy; chỉ, cho biết như đang chỉ đường. Có\ntiếng răng rắc dưới máy chiếu: màn chiếu cho cả lớp xem ảnh\nđang biết chạy. Mực dùng đuôi vẽ lên bóng tối 見せます（みせます）\n— Cho xem, cho thấy.\n\n\n\n\n                                   22","Chiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Khi ngang qua tủ mượn sách,\ncon cáo cho bạn mượn sách bằng một tay. Những nét mực tự sắp\nthành 貸します（かします） — Cho mượn, cho vay; An lập tức ghi nhớ\ncảnh ấy. Không kịp gọi Mực, An thấy ở chồng sách con thỏ đi mượn\nsách và ôm chặt không trả. Tiếng Nhật vang lên từ chính vật ấy:\n借ります（かります） — Mượn, vay. Dưới ánh đèn nơi bàn học sinh,\nhọc sinh học tiếng Nhật đến mức vở phát sáng. Một dòng chữ khác\nphát sáng: 勉強します（べんきょうします） — Học, học tập. Còn tại tập\nvở, học trò được thầy truyền kiến thức qua ánh sáng. An thì thầm\nphù hiệu 習います（ならいます） — Học, được ai dạy, nghe nó hòa\nvào tiếng tim mình. Chạm vào bút máy, An bỗng nhìn thấy máy\ntính được sử dụng như tàu bay. Dòng chữ 使います（つかいます） —\nSử dụng, dùng hiện ra giữa không khí.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Họ vừa đến hộp bút thì chú gấu\nmang    chiếc   cặp   cao   hơn   đầu.   An   thử   đọc   phù   hiệu\n持ちます（もちます） — Cầm, mang; có, sở hữu và cảnh tượng đứng\nyên. Ngay bên giá sách, cuốn sách được đặt lên trần nhà thay vì\nmặt bàn. Ánh sáng rót thành ký tự 置きます（おきます） — Đặt, để\nnhư đang chỉ đường. Có tiếng răng rắc dưới tủ trưng bày: hộp bút\nmở ra, phun 100 cây bút. Mực dùng đuôi vẽ lên bóng tối\n出します（だします） — Đưa ra, lấy ra; nộp. Tiến thêm một bước đến\ncửa sổ trái, An bắt gặp cửa sổ bị đóng cái RẦM làm cả lớp giật\nmình. Phù hiệu vừa thức dậy mang tên 開けます（あけます） — Mở.\nKhi ngang qua cửa sổ phải, bóng đèn tắt phụt, lớp chìm vào bóng\ntối. Những nét mực tự sắp thành 閉めます（しめます） — Đóng; An\nlập tức ghi nhớ cảnh ấy.\n\n\n\n\n                                  23","An biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Dưới ánh đèn nơi đèn lớp, bóng\nđèn bật sáng, mọi thứ lóe lên. Một dòng chữ khác phát sáng:\n消します（けします） — Tắt; xóa. Còn tại quạt trần, đồng hồ nhỏ giọt\ntừng chút như mật ong. An thì thầm phù hiệu つけます（つけます）\n— Bật (điện, thiết bị...), nghe nó hòa vào tiếng tim mình. Chạm vào\nđồng hồ, An bỗng nhìn thấy rùa chậm rãi đi qua bàn trong 100\nnăm. Dòng chữ ちょっと（ちょっと） — Một chút, một lát hiện ra giữa\nkhông khí. Ở góc máy tính, báo thức kêu, cả lớp chạy ngay lập tức.\nMực    kêu   lên   một    tiếng;        trên   nền   nhà   xuất   hiện\nゆっくり（ゆっくり） — Chậm rãi, thong thả. Họ vừa đến kệ cặp thì\nngười đầu tiên đội chiếc mũ số 1. An thử đọc phù hiệu すぐ（すぐ）\n— Ngay, ngay lập tức và cảnh tượng đứng yên.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Có tiếng răng rắc dưới\nngăn kéo: người tiếp theo trượt theo một đường ray số 2. Mực\ndùng đuôi vẽ lên bóng tối はじめに（はじめに） — Đầu tiên, trước hết.\nTiến thêm một bước đến chậu cây, An bắt gặp người cuối cùng\nchốt cửa bằng dấu chấm hết. Phù hiệu vừa thức dậy mang tên\nつぎに（つぎに） — Tiếp theo, sau đó. Khi ngang qua bảng bài tập,\nbàn tay khổng lồ chắp lại xin nhờ giúp đỡ. Những nét mực tự sắp\nthành 最後に（さいごに） — Cuối cùng; An lập tức ghi nhớ cảnh ấy.\nKhông kịp gọi Mực, An thấy ở hòm thư chiếc vở đông cứng, giữ\nnguyên như cũ. Tiếng Nhật vang lên từ chính vật ấy:\nお願いします（おねがいします） — Làm ơn; xin nhờ. Dưới ánh đèn nơi\ncửa ra, cả lớp bước ra qua cánh cổng kết thúc. Một dòng chữ khác\nphát sáng: そのまま（そのまま） — Cứ để nguyên như vậy.\n\n  Khi chiếc khóa bật lên, một phong thư rơi ra. Trên đó viết:\n  “Vượt trạm kiểm soát trước khi cổng cuối cùng đóng.”\n\n\n\n                                   24","TẬ P I I   /   CHƯƠNG 07   /   PHÙ HIỆU 135–155\n\n\n\nTrạm kiểm soát của người gác\ncổng vô hình\n   Cánh cổng phân đôi thành lối vào và lối ra. Trên tường có\n   hàng trăm quy định; ai nhầm lẫn giữa điều được làm và điều\n   nguy hiểm sẽ bị biến thành một tấm ảnh.\n\nAn phải đi qua từng bàn kiểm tra, bước theo chỉ dẫn của Mực và\ncứu một người bị nhốt trong bản photocopy. Những đồ vật hằng\nngày đột nhiên trở thành bằng chứng của một vụ án.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Tiến thêm một\nbước đến cổng soát vé, An bắt gặp cả đám người chen nhau đi vào\nmột ô cửa. Phù hiệu vừa thức dậy mang tên 入ります（はいります）\n— Vào, đi vào. Khi ngang qua cửa ra vào, một con voi đi ra khiến\ncửa chật ních. Những nét mực tự sắp thành 出ます（でます） — Ra,\nđi ra; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở ghế\nchờ chiếc ghế kéo người ngồi xuống như nam châm. Tiếng Nhật\nvang lên từ chính vật ấy: 座ります（すわります） — Ngồi. Dưới ánh\nđèn nơi bảng điện tử, cột cờ tự đứng thẳng nghiêm trang. Một\ndòng chữ khác phát sáng: 立ちます（たちます） — Đứng, đứng lên.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Chạm vào làn đỗ xe, An bỗng\nnhìn thấy xe ô tô dừng gấp, bánh xe bốc khói. Dòng chữ\n止めます（とめます） — Dừng, làm cho dừng; đỗ xe hiện ra giữa\nkhông khí. Ở máy ảnh, máy ảnh chụp ảnh làm người hóa thành\n\n\n\n                                   25","tượng. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n撮ります（とります） — Chụp, quay. Họ vừa đến vạch cấm chạm thì\nbàn tay khổng lồ chạm vào nút đỏ làm chuông reo. An thử đọc phù\nhiệu 触ります（さわります） — Sờ, chạm vào và cảnh tượng đứng\nyên. Ngay bên thùng rác, người máy vứt cả ngọn núi rác xuống\nthùng. Ánh sáng rót thành ký tự 捨てます（すてます） — Vứt, bỏ đi\nnhư đang chỉ đường.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Tiến thêm một bước đến bảng cấm\nthuốc, An bắt gặp điếu thuốc khổng lồ thổi ra mây khói. Phù hiệu\nvừa thức dậy mang tên タバコを吸います（すいます） — Hút thuốc.\nKhi ngang qua quầy nước, chai rượu xoay như vòi rồng. Những\nnét mực tự sắp thành お酒（おさけ） — Rượu, đồ uống có cồn; An lập\ntức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở bức ảnh bức\nảnh gia đình nhảy ra khỏi khung. Tiếng Nhật vang lên từ chính vật\nấy: 写真（しゃしん） — Ảnh, bức ảnh. Dưới ánh đèn nơi máy\nphotocopy, máy photocopy nhân bản 100 người giấy. Một dòng chữ\nkhác phát sáng: コピー（コピー） — Bản sao; photocopy.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Chạm vào cặp hồ sơ, An bỗng\nnhìn thấy hồ sơ giấy bay quanh phòng như đàn chim. Dòng chữ\n資料（しりょう） — Tài liệu hiện ra giữa không khí. Ở tủ catalog, tập\ncatalog sản phẩm tự lật vun vút. Mực kêu lên một tiếng; trên nền\nnhà xuất hiện カタログ（カタログ） — Catalog, cuốn danh mục sản\nphẩm. Họ vừa đến đơn khai địa chỉ thì mã địa chỉ dài quấn quanh\ncây bút. An thử đọc phù hiệu 住所（じゅうしょ） — Địa chỉ và cảnh\ntượng đứng yên. Ngay bên máy điện thoại, điện thoại đọc ra dãy số\nbằng    giọng    robot.   Ánh        sáng   rót   thành   ký   tự\n電話番号（でんわばんごう） — Số điện thoại như đang chỉ đường.\n\n\n\n                                26","Tiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Tiến thêm một bước đến\nbảng tên, An bắt gặp bảng tên khổng lồ phát sáng trên đầu người.\nPhù hiệu vừa thức dậy mang tên 名前（なまえ） — Tên. Khi ngang\nqua biển nguy hiểm, biển nguy hiểm đỏ rực phun tia sét. Những\nnét mực tự sắp thành 危ない（あぶない） — Nguy hiểm; nguy quá; An\nlập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở tủ đồ quý\nviên ngọc quan trọng được giữ trong két sắt. Tiếng Nhật vang lên\ntừ chính vật ấy: 大切「な」（たいせつ） — Quan trọng, quý giá. Dưới\nánh đèn nơi quầy bảo vệ, người gác cửa cúi chào xin phép bước\nvào. Một dòng chữ khác phát sáng: 大丈夫「な」（だいじょうぶ） —\nỔn, không sao; an toàn.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Chạm vào cửa kiểm tra, An bỗng\nnhìn thấy cánh cửa kiểm tra bật đèn xanh cho qua. Dòng chữ\n失礼します（しつれいします） — Xin phép; xin thất lễ hiện ra giữa\nkhông khí.\n\n  Người gác cổng cuối cùng cúi đầu để họ đi qua. Dưới chân An\n  xuất hiện bản đồ một công viên rộng lớn.\n\n\n\n\n                               27","TẬ P I I   /   CHƯƠNG 08   /   PHÙ HIỆU 156–175\n\n\n\nCông viên mọc ra từ một tấm\nbưu thiếp\n   Công viên trông nhỏ như tấm bưu thiếp, nhưng hễ bước qua\n   cổng, núi, sông và biển đều trải ra vô tận. Trên trời treo tấm\n   áp phích: “Chuyến đi này chỉ dành cho người dám đi.”\n\nAn dẫn Mực băng từ khu cắm trại sang rừng, trèo núi, rồi ghé\nnhững công trình vừa đẹp vừa kỳ quái. Mỗi hoạt động đánh dấu\nmột nấc trên con đường đi tìm tiếng gọi của em gái.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Khi ngang qua\ncổng công viên, người leo thẳng lên đỉnh cổng như người nhện.\nNhững nét mực tự sắp thành 登ります（のぼります） — Leo, trèo; An\nlập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở quầy lưu trú\ncon gấu ngủ trọ qua đêm trong túp lều. Tiếng Nhật vang lên từ\nchính vật ấy: 泊まります（とまります） — Trọ lại, ở qua đêm. Dưới\nánh đèn nơi bàn dọn đồ, chổi thần dọn sạch bụi trong một giây.\nMột dòng chữ khác phát sáng: 掃除します（そうじします） — Dọn\ndẹp, vệ sinh. Còn tại dây phơi, máy giặt làm mưa xà phòng lên bầu\ntrời. An thì thầm phù hiệu 洗濯します（せんたくします） — Giặt giũ,\nnghe nó hòa vào tiếng tim mình.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Ở sân tập, vận động viên luyện\ntập đến khi chân phát sáng. Mực kêu lên một tiếng; trên nền nhà\nxuất hiện 練習します（れんしゅうします） — Luyện tập. Họ vừa đến\n\n\n\n                                   28","đường đi bộ thì đàn vịt đi dạo thành hàng qua lối nhỏ. An thử đọc\nphù hiệu 散歩します（さんぽします） — Đi dạo và cảnh tượng đứng\nyên. Ngay bên quầy mua sắm, giỏ mua sắm mọc cánh và chạy\nvòng     công      viên.   Ánh    sáng     rót    thành      ký    tự\n買い物します（かいものします） — Mua sắm như đang chỉ đường. Có\ntiếng răng rắc dưới phòng triển lãm: cô giáo tham quan bảo tàng\nghi    chú   như    máy.   Mực   dùng    đuôi    vẽ   lên   bóng   tối\n見学します（けんがくします） — Tham quan để học hỏi.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Khi ngang qua xe du lịch, vali du\nlịch nổ tung ra một bản đồ thế giới. Những nét mực tự sắp thành\n旅行します（りょこうします） — Du lịch; An lập tức ghi nhớ cảnh ấy.\nKhông kịp gọi Mực, An thấy ở núi giả ngọn núi nhỏ đội chiếc mũ\ntuyết khổng lồ. Tiếng Nhật vang lên từ chính vật ấy: 山（やま） —\nNúi. Dưới ánh đèn nơi sông nhỏ, con sông chảy thành hình chữ S\ntrong sân. Một dòng chữ khác phát sáng: 川（かわ） — Sông. Còn tại\nbãi biển, con cá voi lao ra giữa biển xanh. An thì thầm phù hiệu\n海（うみ） — Biển, nghe nó hòa vào tiếng tim mình.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Ở bãi cỏ, công viên có cỏ mọc\ncao hơn cả người. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n公園（こうえん） — Công viên. Họ vừa đến đền thần đạo thì tượng\nthần biến thành cổng đền đỏ rực. An thử đọc phù hiệu\n神社（じんじゃ） — Đền Thần đạo và cảnh tượng đứng yên. Ngay bên\ncổng chùa, tiếng chuông chùa to như sấm vang lên. Ánh sáng rót\nthành ký tự お寺（おてら） — Chùa như đang chỉ đường. Có tiếng\nrăng rắc dưới khách sạn mini: khách sạn di động cao 100 tầng\nđứng giữa hồ. Mực dùng đuôi vẽ lên bóng tối ホテル（ホテル） —\nKhách sạn.\n\n\n\n                                 29","Tiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Khi ngang qua bục đếm\nlần, chiếc số 1 được khắc lên núi như một lần duy nhất. Những nét\nmực tự sắp thành 一度（いちど） — Một lần; An lập tức ghi nhớ\ncảnh ấy. Không kịp gọi Mực, An thấy ở bảng số 0 con số 0 trống\nrỗng chưa từng xảy ra lần nào. Tiếng Nhật vang lên từ chính vật\nấy: 一度も（いちども） — Chưa/không một lần nào. Dưới ánh đèn nơi\nđường trở về, mũi tên SAU dẫn ngược về một con đường khác. Một\ndòng chữ khác phát sáng: 後（あと） — Sau, sau khi. Còn tại hàng\ncây thay lá, cây thay lá dần dần từng chiếc một. An thì thầm phù\nhiệu だんだん（だんだん） — Dần dần, từ từ, nghe nó hòa vào tiếng\ntim mình.\n\n  Họ ngủ lại cạnh hồ. Trong giấc mơ, thời tiết của ngày mai đã đổi\n  ba lần; bản đồ dẫn thẳng tới đài khí tượng.\n\n\n\n\n                               30","TẬ P I I   /   CHƯƠNG 09   /   PHÙ HIỆU 176–195\n\n\n\nNgã tư nơi thời tiết biết suy\nnghĩ\n   Bốn con đường tỏa ra từ một đài khí tượng: bên phải là mưa,\n   bên trái là tuyết, phía trước là gió và sau lưng là mặt trời. Ông\n   quản đài không cho đi nếu An chọn đường mà không quan\n   sát tín hiệu.\n\nHọ đi qua ngã tư đang tự quay như trò rubik. Bất kỳ lời phỏng\nđoán nào của An cũng có thể thành sự thật: nghĩ đến tuyết là tuyết\nrơi, nghĩ đến nắng là bầu trời sáng.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Khi ngang qua\nống đo mưa, mưa trút xuống từ một cái ô khổng lồ. Những nét\nmực tự sắp thành 雨が降ります（あめがふります） — Mưa, trời mưa ;\nAn lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở máy đo\ntuyết tuyết rơi từ máy làm cả đất trắng xóa. Tiếng Nhật vang lên từ\nchính vật ấy: 雪が降ります（ゆきがふります） — Tuyết rơi. Dưới ánh\nđèn nơi cối xay gió, cơn gió khổng lồ thổi bay mái nhà. Một dòng\nchữ khác phát sáng: 風が吹きます（かぜがふきます） — Gió thổi. Còn\ntại mặt trời nhân tạo, mặt trời ló ra, trời quang sáng rực. An thì\nthầm phù hiệu 晴れます（はれます） — Trời quang, trời nắng, nghe\nnó hòa vào tiếng tim mình.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Ở đám mây, mây xám kéo đến\ntrùm kín cả thành phố. Mực kêu lên một tiếng; trên nền nhà xuất\n\n\n\n                                   31","hiện 曇ります（くもります） — Trời nhiều mây, âm u. Họ vừa đến ghế\nsuy nghĩ thì ông già ngồi suy nghĩ đến mức khói bốc trên đầu. An\nthử đọc phù hiệu 考えます（かんがえます） — Suy nghĩ, cân nhắc và\ncảnh tượng đứng yên. Ngay bên sổ tri thức, quyển sổ bật chữ TÔI\nBIẾT đầy sao. Ánh sáng rót thành ký tự 知ります（しります） — Biết,\nbiết được như đang chỉ đường. Có tiếng răng rắc dưới album ký ức:\nalbum ảnh tự mở làm ký ức ùa về. Mực dùng đuôi vẽ lên bóng tối\n思い出します（おもいだします） — Nhớ lại, chợt nhớ ra.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Khi ngang qua đường nhựa, con\nđường tự trải dài tới tận chân trời. Những nét mực tự sắp thành\n道（みち） — Đường, con đường; An lập tức ghi nhớ cảnh ấy. Không\nkịp gọi Mực, An thấy ở góc phố góc phố xoay như chiếc rubik.\nTiếng Nhật vang lên từ chính vật ấy: 角（かど） — Góc, góc đường.\nDưới ánh đèn nơi ngã tư, ngã tư mọc ra bốn con rồng chỉ hướng.\nMột dòng chữ khác phát sáng: 交差点（こうさてん） — Ngã tư, giao lộ.\nCòn tại đèn giao thông, đèn giao thông nháy đỏ vàng xanh loạn xạ.\nAn thì thầm phù hiệu 信号（しんごう） — Đèn tín hiệu, đèn giao\nthông, nghe nó hòa vào tiếng tim mình.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Ở mũi tên phải, một bàn tay\nphải to lớn vẫy từ đám mây. Mực kêu lên một tiếng; trên nền nhà\nxuất hiện 右（みぎ） — Bên phải. Họ vừa đến mũi tên trái thì một\nbàn tay trái to lớn lơ lửng ngược lại. An thử đọc phù hiệu\n左（ひだり） — Bên trái và cảnh tượng đứng yên. Ngay bên khúc\ncua, con đường uốn cong chữ U để rẽ gấp. Ánh sáng rót thành ký\ntự 曲がります（まがります） — Rẽ, quẹo như đang chỉ đường. Có\n\n\n\n\n                               32","tiếng răng rắc dưới vạch qua đường: một con voi băng qua vạch\ntrắng   làm   rung   đất.   Mực   dùng   đuôi   vẽ   lên   bóng   tối\n渡ります（わたります） — Băng qua, đi qua.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Khi ngang qua cầu vượt,\ncây cầu lật lên như chiếc bánh mì. Những nét mực tự sắp thành\n橋（はし） — Cầu; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực,\nAn thấy ở bản đồ trời bản đồ thời tiết đổi từ mưa sang nắng. Tiếng\nNhật vang lên từ chính vật ấy: 天気（てんき） — Thời tiết. Dưới ánh\nđèn nơi biển giả định, chữ NẾU khổng lồ mở ra cánh cửa giả định.\nMột dòng chữ khác phát sáng: もし（もし） — Nếu, giả sử. Còn tại\nbảng so sánh, một chiếc cân hỏi bao nhiêu cũng chưa đủ. An thì\nthầm phù hiệu いくら（いくら） — Cho dù... bao nhiêu đi nữa; bao\nnhiêu, nghe nó hòa vào tiếng tim mình.\n\n  Phía bên kia cây cầu có một tiếng chuông cứu thương. Mực tái\n  mặt vì ký ức về người em gái bỗng nhòe đi.\n\n\n\n\n                                  33","TẬ P I I   /   CHƯƠNG 10   /   PHÙ HIỆU 196–216\n\n\n\nBệnh viện chữa những vết\nthương của trí nhớ\n   Trên bảng bệnh viện ghi: “Người quên tên sẽ mất đường về.”\n   An phát hiện trang đầu của cuốn sổ trắng đã rơi khỏi túi. Cô\n   vội đuổi theo nó qua hành lang, kéo theo một chuỗi tai nạn kỳ\n   cục.\n\nCác y tá phải giữ cho đám máy móc khỏi phá vỡ những đồ vật\nquan trọng. An vừa lo lắng vừa vội vàng, nhưng Mực nhắc cô rằng\ncố quá sức chỉ khiến mọi chuyện tệ hơn.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Khi ngang qua\nbảng ghi nhớ, cục tẩy xóa sạch trí nhớ trên bảng. Những nét mực\ntự sắp thành 忘れます（わすれます） — Quên; An lập tức ghi nhớ\ncảnh ấy. Không kịp gọi Mực, An thấy ở bàn đồ thất lạc đôi tất biến\nmất khỏi túi như phép thuật. Tiếng Nhật vang lên từ chính vật ấy:\nなくします（なくします） — Làm mất, đánh mất. Dưới ánh đèn nơi\nghế lo lắng, chiếc đồng hồ lo lắng đập liên hồi. Một dòng chữ khác\nphát sáng: 心配します（しんぱいします） — Lo lắng. Còn tại cửa cấp\ncứu, y tá chạy vội như tên lửa vào phòng cấp cứu. An thì thầm phù\nhiệu 急ぎます（いそぎます） — Vội, khẩn trương, nghe nó hòa vào\ntiếng tim mình.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Ở máy tập thể lực, người lực sĩ\ncố quá sức nâng cả bệnh viện. Mực kêu lên một tiếng; trên nền\n\n\n\n                                   34","nhà xuất hiện 無理をします（むりをします） — Cố quá sức, làm quá\nsức. Họ vừa đến tủ thay đồ thì áo khoác tự cởi khỏi người rồi bỏ\nchạy. An thử đọc phù hiệu 脱ぎます（ぬぎます） — Cởi (quần áo, giày\ndép...) và cảnh tượng đứng yên. Ngay bên quầy thanh toán, máy\nthanh toán nuốt từng đồng xu. Ánh sáng rót thành ký tự\n払います（はらいます） — Trả, thanh toán như đang chỉ đường. Có\ntiếng răng rắc dưới đồ dễ vỡ: chiếc bát vỡ vụn khi chạm vào không\nkhí. Mực dùng đuôi vẽ lên bóng tối 壊します（こわします） — Làm\nhỏng, làm vỡ.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Khi ngang qua bồn rửa bẩn, mực\nđen bắn tung làm cả sàn bẩn thỉu. Những nét mực tự sắp thành\n汚します（よごします） — Làm bẩn; An lập tức ghi nhớ cảnh ấy.\nKhông kịp gọi Mực, An thấy ở tủ thuốc viên thuốc khổng lồ lăn\nrầm rầm qua hành lang. Tiếng Nhật vang lên từ chính vật ấy:\n薬（くすり） — Thuốc. Dưới ánh đèn nơi nhiệt kế, nhiệt kế đỏ rực\nchỉ cơn sốt. Một dòng chữ khác phát sáng: 熱（ねつ） — Sốt; nhiệt.\nCòn tại giường bệnh, vi khuẩn màu xanh nhảy múa trên giường\nbệnh. An thì thầm phù hiệu 病気（びょうき） — Bệnh, bệnh tật, nghe\nnó hòa vào tiếng tim mình.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Ở phòng khám, bệnh viện biến\nthành hình trái tim có cửa. Mực kêu lên một tiếng; trên nền nhà\nxuất hiện 病院（びょういん） — Bệnh viện. Họ vừa đến quầy bảo\nhiểm thì thẻ bảo hiểm khổng lồ che kín quầy. An thử đọc phù hiệu\n保険証（ほけんしょう） — Thẻ bảo hiểm và cảnh tượng đứng yên.\nNgay bên móc áo khoác, áo khoác bay từ móc và quấn lấy người.\nÁnh sáng rót thành ký tự 上着（うわぎ） — Áo khoác, áo mặc ngoài\n\n\n\n\n                               35","như đang chỉ đường. Có tiếng răng rắc dưới tủ đồ lót: cái quần lót\nleo lên đỉnh tủ như cờ. Mực dùng đuôi vẽ lên bóng tối\n下着（したぎ） — Đồ lót.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Khi ngang qua giá giày,\nđôi giày tự bước đi không cần chân. Những nét mực tự sắp thành\n靴（くつ） — Giày; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực,\nAn thấy ở ngăn tất đôi tất biến thành hai con sâu nhiều màu. Tiếng\nNhật vang lên từ chính vật ấy: 靴下（くつした） — Tất, vớ. Dưới ánh\nđèn nơi tủ đồ quý, hộp kho báu đánh dấu QUAN TRỌNG. Một dòng\nchữ khác phát sáng: 大切「な」（たいせつ） — Quan trọng, quý giá.\nCòn tại bảng nguy hiểm, cảnh báo nguy hiểm hú còi đỏ chói. An thì\nthầm phù hiệu 危ない（あぶない） — Nguy hiểm, nguy hiểm đấy!,\nnghe nó hòa vào tiếng tim mình.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Ở máy chờ lâu, một hàng người chờ\nmãi mà không đến lượt. Mực kêu lên một tiếng; trên nền nhà xuất\nhiện なかなか（なかなか） — Mãi mà không..., không dễ....\n\n  Đến cuối hành lang, An tìm lại trang sổ. Có ai đó đã viết lên đó\n  ba chữ: “Nhà máy tăng ca.”\n\n\n\n\n                                  36","TẬ P I I   /    CHƯƠNG 11       /    PHÙ HIỆU 217–236\n\n\n\nNhà máy tăng ca tới ngày tận\nthế\n   Ở nhà máy, mọi nhân viên phải chạy đua với chiếc đồng hồ\n   không bao giờ dừng. Ông quản đốc đội chiếc mũ làm bằng đề\n   thi, còn dây chuyền sản xuất liên tục nhả ra câu hỏi chưa có\n   đáp án.\n\nAn lần theo dây chuyền: kim đồng hồ, van xoay, cần kéo, nút ấn,\nbảng đổi ca, rồi hạn chót. Một đáp án sai có thể biến cả nhà máy\nthành đống giấy.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Không kịp gọi\nMực, An thấy ở máy chấm công máy chấm công nuốt người rồi\nnhả ra thẻ đi làm. Tiếng Nhật vang lên từ chính vật ấy:\n出勤します（しゅっきんします） — Đi làm, đến nơi làm việc. Dưới ánh\nđèn nơi bảng tăng ca, đồng hồ tăng ca quay thêm 12 giờ liên tục.\nMột dòng chữ khác phát sáng: 残業します（ざんぎょうします） —\nLàm thêm giờ, tăng ca. Còn tại vali công tác, chiếc vali công tác tự\nbay        qua     biên        giới.       An     thì     thầm    phù    hiệu\n出張します（しゅっちょうします） — Đi công tác, nghe nó hòa vào\ntiếng tim mình. Chạm vào đồng hồ kịp giờ, An bỗng nhìn thấy kim\nđồng       hồ     lao     về        đích    vừa     kịp    giờ.   Dòng   chữ\n間に合います（まにあいます） — Kịp, kịp giờ hiện ra giữa không khí.\n\n\n\n\n                                           37","Chiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Họ vừa đến máy báo trễ thì\nchuông trễ réo làm cả nhà máy giật mình. An thử đọc phù hiệu\n遅れます（おくれます） — Muộn, trễ và cảnh tượng đứng yên. Ngay\nbên van tròn, van tròn xoay làm trời đất đảo lộn. Ánh sáng rót\nthành ký tự 回します（まわします） — Xoay, vặn như đang chỉ\nđường. Có tiếng răng rắc dưới cần kéo: cần kéo dài như tàu hỏa\nkéo   cả   nhà    máy.   Mực    dùng   đuôi   vẽ   lên   bóng   tối\n引きます（ひきます） — Kéo. Tiến thêm một bước đến nút nhấn, An\nbắt gặp nút nhấn đỏ bắn người lên không trung. Phù hiệu vừa\nthức dậy mang tên 押します（おします） — Ấn, nhấn; đẩy.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Không kịp gọi Mực, An thấy ở\nbảng đổi ca bảng đổi ca lật màu từ xanh sang vàng. Tiếng Nhật\nvang lên từ chính vật ấy: 変えます（かえます） — Thay đổi. Dưới ánh\nđèn nơi bản báo cáo, báo cáo dài nghìn trang rơi như thác. Một\ndòng chữ khác phát sáng: レポート（レポート） — Bản báo cáo, bài\nbáo cáo. Còn tại phòng thi, bài thi xuất hiện với 1.000 câu hỏi. An\nthì thầm phù hiệu 試験（しけん） — Kỳ thi, bài thi, nghe nó hòa vào\ntiếng tim mình. Chạm vào bảng đáp án, An bỗng nhìn thấy đáp án\nvàng bật ra như chiếc chìa khóa. Dòng chữ 答え（こたえ） — Câu trả\nlời, đáp án hiện ra giữa không khí.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Họ vừa đến hộp câu hỏi thì một\ndấu hỏi khổng lồ nhảy từ hộp. An thử đọc phù hiệu\n質問（しつもん） — Câu hỏi và cảnh tượng đứng yên. Ngay bên biển\ngiải nghĩa, chữ Ý NGHĨA hiện trên bảng như đèn neon. Ánh sáng\nrót thành ký tự 意味（いみ） — Ý nghĩa như đang chỉ đường. Có\ntiếng răng rắc dưới bảng kanji: chữ Kanji khổng lồ đội mũ\n\n\n                                  38","samurai. Mực dùng đuôi vẽ lên bóng tối 漢字（かんじ） — Chữ Hán,\nKanji. Tiến thêm một bước đến hạn nộp, An bắt gặp kéo cắt đứt lịch\nngay ngày hạn chót. Phù hiệu vừa thức dậy mang tên\n締め切り（しめきり） — Hạn chót, deadline.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Không kịp gọi Mực, An\nthấy ở chuông báo sớm chuông báo sớm rung trước khi mặt trời\nmọc. Tiếng Nhật vang lên từ chính vật ấy: 早めに（はやめに） —\nSớm hơn một chút, sớm hơn thường lệ. Dưới ánh đèn nơi biển tuyệt\nđối, cánh tay chỉ biển TUYỆT ĐỐI, không ngoại lệ. Một dòng chữ\nkhác phát sáng: 絶対に（ぜったいに） — Tuyệt đối, nhất định. Còn tại\nmáy dự đoán, quả cầu pha lê đoán điều có lẽ xảy ra. An thì thầm\nphù hiệu 多分（たぶん） — Có lẽ, chắc là, nghe nó hòa vào tiếng tim\nmình. Chạm vào cánh cửa chắc chắn, An bỗng nhìn thấy người\nmáy quả quyết chắc chắn tới mức gật 100 lần. Dòng chữ\nきっと（きっと） — Chắc chắn, chắc là hiện ra giữa không khí.\n\n  Mực nhảy lên máy chấm công và gõ một câu trả lời cuối cùng.\n  Chỗ tối nhất trong xưởng mở ra một nhà kho chứa mọi vật đã\n  biến mất.\n\n\n\n\n                                39","TẬ P I I I • 6 TẬ P • 2 6 C H Ư Ơ N G\n\n\n\n\nTHẾ GIỚI CÓ HÌNH\nDÁNG\nVật, người, nơi chốn và thời gian trở về đúng vị\ntrí.\n\n\n\n\n                      三","TẬ P I I I   /    CHƯƠNG 12      /   PHÙ HIỆU 237–257\n\n\n\nKho chứa những thứ có và\nkhông có\n    Nhà kho im lặng tới mức An nghe thấy tiếng thở của bụi.\n    Người thủ kho nói: “Muốn tìm ai đó, trước hết phải biết thứ gì\n    tồn tại, ở trong hay ở ngoài, ở trên hay ở dưới.”\n\nMột chiếc cặp bỗng xuất hiện mà không có ai mang đến. Con mèo\nđội vương miện bước ra, tự xưng là anh trai của Mực; nó biết\nđường đến ga tàu nhưng chỉ chịu dẫn nếu An phân biệt được vị trí\ncủa từng thứ.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Không kịp gọi\nMực, An thấy ở cửa kho một chiếc cặp tự xuất hiện trên kệ dù\nkhông        ai   đặt.   Tiếng   Nhật    vang   lên   từ   chính   vật   ấy:\nあります（あります） — Có, tồn tại (đồ vật, thực vật...). Dưới ánh đèn\nnơi chuồng thú, mèo và người thật chạy nhảy, chứng tỏ có sinh vật\nsống. Một dòng chữ khác phát sáng: います（います） — Có, tồn tại\n(người, động vật). Còn tại hòn đá, đồ vật mọc mắt nhảy khỏi chiếc\nhộp. An thì thầm phù hiệu 物（もの） — Đồ vật, vật, nghe nó hòa vào\ntiếng tim mình. Chạm vào cặp sách, An bỗng nhìn thấy cặp xách\nphình ra chứa cả thành phố. Dòng chữ 鞄（かばん） — Túi, cặp hiện\nra giữa không khí.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Họ vừa đến bàn gỗ thì bàn làm\nviệc tự đi như chân voi. An thử đọc phù hiệu 机（つくえ） — Bàn\n\n\n\n                                        41","học, bàn làm việc và cảnh tượng đứng yên. Ngay bên ghế, chiếc ghế\nnhảy múa giữa nhà kho. Ánh sáng rót thành ký tự 椅子（いす） —\nGhế như đang chỉ đường. Có tiếng răng rắc dưới tivi cũ: màn hình\ntivi chiếu bóng ma trong thùng. Mực dùng đuôi vẽ lên bóng tối\nテレビ（テレビ） — Tivi. Tiến thêm một bước đến tủ lạnh, An bắt\ngặp chiếc tủ lạnh mở ra một cánh cổng Bắc Cực. Phù hiệu vừa thức\ndậy mang tên 冷蔵庫（れいぞうこ） — Tủ lạnh.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Không kịp gọi Mực, An thấy ở cửa\nsổ cửa sổ mọc cánh như chim và bay mất. Tiếng Nhật vang lên từ\nchính vật ấy: 窓（まど） — Cửa sổ. Dưới ánh đèn nơi bức tường, bức\ntường uốn cong thành hình xoắn ốc. Một dòng chữ khác phát sáng:\n壁（かべ） — Tường, bức tường. Còn tại sân sau, cả sân vườn mọc\ntrong chiếc cốc nhỏ. An thì thầm phù hiệu 庭（にわ） — Sân, vườn,\nnghe nó hòa vào tiếng tim mình. Chạm vào thùng carton, An bỗng\nnhìn thấy hộp carton mở ra một cái hộp nhỏ hơn vô hạn. Dòng chữ\n箱（はこ） — Hộp hiện ra giữa không khí.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Họ vừa đến ổ mèo thì con mèo\nđội vương miện gầm như sư tử. An thử đọc phù hiệu 猫（ねこ） —\nCon mèo và cảnh tượng đứng yên. Ngay bên chuồng chó, con chó\ncao bằng ngựa vẫy đuôi ầm ầm. Ánh sáng rót thành ký tự\n犬（いぬ） — Con chó như đang chỉ đường. Có tiếng răng rắc dưới\ngóc học: lớp học thu nhỏ nằm trong lòng bàn tay. Mực dùng đuôi\nvẽ lên bóng tối 教室（きょうしつ） — Phòng học, lớp học. Tiến thêm\nmột bước đến bên cạnh tủ, An bắt gặp một chú mèo đứng ngay\nbên cạnh tủ. Phù hiệu vừa thức dậy mang tên 隣（となり） — Bên\ncạnh, kế bên.\n\n\n\n\n                               42","Tiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Không kịp gọi Mực, An\nthấy ở hộp bên trong con cá vàng bơi bên trong cái hộp kính. Tiếng\nNhật vang lên từ chính vật ấy: 中（なか） — Bên trong, trong. Dưới\nánh đèn nơi sân bên ngoài, con chó chạy ở ngoài hàng rào. Một\ndòng chữ khác phát sáng: 外（そと） — Bên ngoài, ngoài. Còn tại giá\ncao, các đồ vật ở trên đầu tủ xếp thành núi. An thì thầm phù hiệu\n上（うえ） — Trên, bên trên, nghe nó hòa vào tiếng tim mình. Chạm\nvào ngăn thấp, An bỗng nhìn thấy chiếc hầm đào xuống dưới tận\nlòng đất. Dòng chữ 下（した） — Dưới, bên dưới hiện ra giữa không\nkhí.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Họ vừa đến biển chỉ gần thì ống\nnhòm cho thấy vật ở gần chỉ cách một bước. An thử đọc phù hiệu\n近く（ちかく） — Gần, ở gần; khu vực gần đó và cảnh tượng đứng\nyên.\n\n  An trèo lên chiếc hộp cao nhất và nhìn thấy đường ray chạy\n  ngang trời. Cô không chần chừ nữa.\n\n\n\n\n                                43","TẬ P I I I   /   CHƯƠNG 13   /   PHÙ HIỆU 258–278\n\n\n\nChuyến tàu chạy xuyên qua\nbản đồ\n    Nhà ga có mọi phương tiện: tàu chạy trên sàn, thuyền đi qua\n    tường, xe buýt chở voi và máy bay nhỏ như bàn tay. Một\n    người bán vé nói chuyến duy nhất đến nơi An cần là chuyến\n    bắt buộc phải đổi phương tiện liên tục.\n\nAn mua một tấm vé đã cũ, gặp lại một người bạn tưởng chỉ còn\ntrong ký ức, rồi di chuyển qua từng cửa. Mực sợ nhất chiếc tàu\nngầm đào đường xuyên qua những bức tường.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Dưới ánh đèn nơi\nquầy vé, tiền vàng bay khỏi ví để mua vé tàu. Một dòng chữ khác\nphát sáng: 買います（かいます） — Mua. Còn tại cổng gặp mặt, bạn\ncũ bất ngờ gặp nhau và ôm chầm giữa ga. An thì thầm phù hiệu\n会います（あいます） — Gặp, gặp gỡ, nghe nó hòa vào tiếng tim\nmình. Chạm vào bảng đổi tuyến, An bỗng nhìn thấy hành khách\nđổi từ tàu đỏ sang tàu xanh bằng cầu trượt. Dòng chữ\n乗り換えます（のりかえます） — Đổi xe, chuyển tàu hiện ra giữa\nkhông khí. Ở bậc xuống tàu, người rời toa tàu bước xuống bậc\nthang. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n降ります（おります） — Xuống xe, xuống tàu.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Ngay bên bảng tên ga, biển tên\nnhà ga phát sáng lớn như mặt trăng. Ánh sáng rót thành ký tự\n\n\n\n                                    44","駅（えき） — Nhà ga như đang chỉ đường. Có tiếng răng rắc dưới\ncửa bách hóa: cửa hàng bách hóa biến thành tòa lâu đài. Mực\ndùng đuôi vẽ lên bóng tối デパート（デパート） — Cửa hàng bách hóa.\nTiến thêm một bước đến quầy siêu thị, An bắt gặp siêu thị tự chạy\ntrên bánh xe như xe buýt. Phù hiệu vừa thức dậy mang tên\nスーパー（スーパー） — Siêu thị. Khi ngang qua cây atm, ngân hàng\nphun tiền giấy như suối. Những nét mực tự sắp thành\n銀行（ぎんこう） — Ngân hàng; An lập tức ghi nhớ cảnh ấy.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Dưới ánh đèn nơi hòm thư bưu\nđiện, bưu điện phóng 1.000 phong thư lên trời. Một dòng chữ khác\nphát sáng: 郵便局（ゆうびんきょく） — Bưu điện. Còn tại quầy cà\nphê, quán cà phê tỏa mùi thơm kéo người đi theo. An thì thầm phù\nhiệu 喫茶店（きっさてん） — Quán cà phê, quán giải khát, nghe nó hòa\nvào tiếng tim mình. Chạm vào đường ray tàu, An bỗng nhìn thấy\ncon tàu điện chạy từ giữa bức tranh ra. Dòng chữ 電車（でんしゃ）\n— Tàu điện hiện ra giữa không khí. Ở lối tàu điện ngầm, chiếc tàu\nđiện ngầm đào hầm xuyên tường. Mực kêu lên một tiếng; trên nền\nnhà xuất hiện 地下鉄（ちかてつ） — Tàu điện ngầm.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Ngay bên sân ga shinkansen,\nShinkansen phóng nhanh làm thời gian chậm lại. Ánh sáng rót\nthành ký tự 新幹線（しんかんせん） — Tàu cao tốc Shinkansen như\nđang chỉ đường. Có tiếng răng rắc dưới điểm xe buýt: xe buýt chở\ncả bầy voi đứng dậy vẫy tay. Mực dùng đuôi vẽ lên bóng tối\nバス（バス） — Xe buýt. Tiến thêm một bước đến điểm taxi, An bắt\ngặp taxi màu vàng bay lên trời tìm khách. Phù hiệu vừa thức dậy\n\n\n\n\n                               45","mang tên タクシー（タクシー） — Taxi. Khi ngang qua giá xe đạp, xe\nđạp khổng lồ đạp bằng chân robot. Những nét mực tự sắp thành\n自転車（じてんしゃ） — Xe đạp; An lập tức ghi nhớ cảnh ấy.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Dưới ánh đèn nơi nhà\nchờ sân bay, máy bay nhỏ đến mức nằm gọn trong bàn tay. Một\ndòng chữ khác phát sáng: 飛行機（ひこうき） — Máy bay. Còn tại\nbến thuyền, thuyền trôi xuyên sàn ga thành con sông. An thì thầm\nphù hiệu 船（ふね） — Thuyền, tàu thủy, nghe nó hòa vào tiếng tim\nmình. Chạm vào lối đi bộ, An bỗng nhìn thấy hai bàn chân tự bước\ntrên sợi dây không trung. Dòng chữ 歩きます（あるきます） — Đi bộ\nhiện ra giữa không khí. Ở xe bánh mì, ổ bánh mì mọc cánh bay\nquanh sân ga. Mực kêu lên một tiếng; trên nền nhà xuất hiện\nパン（パン） — Bánh mì.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Ngay bên quầy trà, ấm trà phun hơi\nthành hình đám mây. Ánh sáng rót thành ký tự お茶（おちゃ） —\nTrà, nước chè như đang chỉ đường.\n\n  Ở sân ga cuối, An nhận được thiệp mời đến bữa cơm của gia\n  đình mà cô chưa từng gặp.\n\n\n\n\n                               46","TẬ P I I I   /   CHƯƠNG 14   /   PHÙ HIỆU 279–299\n\n\n\nBữa tối của hai mươi mốt vị\nkhách\n    Ngôi nhà đón An bằng một chiếc bàn dài bất tận. Mỗi ghế\n    dành cho một mối quan hệ, một món ăn hay một lời hỏi\n    thăm; tất cả nhân vật đều nói chuyện cùng lúc, như thể đã\n    biết cô từ lâu.\n\nMực ngồi nghiêm chỉnh cạnh bát cá, còn An phải gọi đúng từng\nngười để chiếc ghế của họ xuất hiện. Khi món ăn biến thành sinh\nvật thật, buổi tiệc lập tức biến thành một cuộc truy đuổi hài hước.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Còn tại ảnh gia\nđình, cả gia đình sống trong một tấm ảnh đang cười. An thì thầm\nphù hiệu 家族（かぞく） — Gia đình, người trong gia đình, nghe nó\nhòa vào tiếng tim mình. Chạm vào ghế cha mẹ, An bỗng nhìn thấy\nbố mẹ ngồi ghế đôi lớn như ngai vàng. Dòng chữ 両親（りょうしん）\n— Bố mẹ, cha mẹ hiện ra giữa không khí. Ở ghế bố, người bố đội mũ\ncao gấp năm lần đầu. Mực kêu lên một tiếng; trên nền nhà xuất\nhiện 父／お父さん（ちち／おとうさん） — Bố, cha. Họ vừa đến ghế\nmẹ thì người mẹ tung chiếc tạp dề khổng lồ. An thử đọc phù hiệu\n母／お母さん（はは／おかあさん） — Mẹ và cảnh tượng đứng yên.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Có tiếng răng rắc dưới ghế anh\ntrai: anh trai nhảy lên chiếc ghế cao nhất. Mực dùng đuôi vẽ lên\nbóng tối 兄／お兄さん（あに／おにいさん） — Anh trai. Tiến thêm một\n\n\n\n                                    47","bước đến ghế chị gái, An bắt gặp chị gái đeo vương miện trên ghế\nhồng.     Phù     hiệu     vừa        thức   dậy    mang      tên\n姉／お姉さん（あね／おねえさん） — Chị gái. Khi ngang qua ghế em\ntrai, em trai tí hon đạp xe quanh chân ghế. Những nét mực tự sắp\nthành 弟（おとうと） — Em trai; An lập tức ghi nhớ cảnh ấy. Không\nkịp gọi Mực, An thấy ở ghế em gái em gái mang theo con gấu bông\nto gấp đôi người. Tiếng Nhật vang lên từ chính vật ấy:\n妹（いもうと） — Em gái.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Còn tại ghế trẻ em, trẻ em trượt\ncầu trượt ra từ dưới bàn. An thì thầm phù hiệu 子供（こども） —\nTrẻ em; con cái, nghe nó hòa vào tiếng tim mình. Chạm vào chuông\ngọi người, An bỗng nhìn thấy có người hỏi AI ĐẤY rồi mọi người\nquay lại. Dòng chữ 誰（だれ） — Ai hiện ra giữa không khí. Ở ghế\nbạn bè, bạn bè nối tay thành vòng tròn quanh bàn. Mực kêu lên\nmột tiếng; trên nền nhà xuất hiện 友達（ともだち） — Bạn, bạn bè.\nHọ vừa đến khay thịt thì miếng thịt phồng to thành một quả bóng.\nAn thử đọc phù hiệu 肉（にく） — Thịt và cảnh tượng đứng yên.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Có tiếng răng rắc dưới đĩa bò:\ncon bò nhảy từ đĩa thịt và kêu ò ò. Mực dùng đuôi vẽ lên bóng tối\n牛肉（ぎゅうにく） — Thịt bò. Tiến thêm một bước đến đĩa heo, An\nbắt gặp con heo hồng ôm đĩa thịt quay vòng. Phù hiệu vừa thức\ndậy mang tên 豚肉（ぶたにく） — Thịt lợn, thịt heo. Khi ngang qua\nđĩa gà, con gà đập cánh làm đĩa thịt bay. Những nét mực tự sắp\nthành 鶏肉（とりにく） — Thịt gà; An lập tức ghi nhớ cảnh ấy. Không\nkịp gọi Mực, An thấy ở giỏ trứng trứng khổng lồ nở ra con rồng\ncon. Tiếng Nhật vang lên từ chính vật ấy: 卵（たまご） — Trứng.\n\n\n\n\n                                 48","Tiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Còn tại rổ rau, rổ rau\nmọc thành khu rừng xanh. An thì thầm phù hiệu 野菜（やさい） —\nRau, rau củ, nghe nó hòa vào tiếng tim mình. Chạm vào mâm trái\ncây, An bỗng nhìn thấy trái cây biết hát hòa thành dàn nhạc. Dòng\nchữ 果物（くだもの） — Trái cây, hoa quả hiện ra giữa không khí. Ở\nbể cá, con cá nhảy từ bể lên ghế ăn. Mực kêu lên một tiếng; trên\nnền nhà xuất hiện 魚（さかな） — Cá. Họ vừa đến bình nước thì ly\nnước   biến   thành   thác   Niagara.   An   thử   đọc   phù   hiệu\n飲み物（のみもの） — Đồ uống, thức uống và cảnh tượng đứng yên.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Có tiếng răng rắc dưới đĩa bánh:\nbánh kẹo đổ xuống bàn như mưa sao. Mực dùng đuôi vẽ lên bóng\ntối お菓子（おかし） — Bánh kẹo, đồ ăn vặt.\n\n  Cả nhà cười vang. Một người mẹ bí ẩn đưa An chiếc đồng hồ\n  không có kim và dặn: “Đừng đến trễ tháp thời gian.”\n\n\n\n\n                                49","TẬ P I I I   /   CHƯƠNG 15   /   PHÙ HIỆU 300–320\n\n\n\nTháp đồng hồ ăn mất thứ Hai\n    Trong tháp, các ngày trong tuần mang hình dáng khác nhau\n    và chạy vòng quanh mặt đồng hồ như những diễn viên.\n    Không ai biết hôm nay là thứ mấy vì tất cả các kim đều tranh\n    nhau đi trước.\n\nAn tìm lại giờ, phút, thời lượng và nhịp nghỉ. Các tấm lịch tháng,\nngày, tuần, năm lần lượt được trả về vị trí như những mảnh ghép\ncủa một tòa nhà.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Chạm vào mặt\nđồng hồ giờ, An bỗng nhìn thấy kim giờ khổng lồ chạy quanh mặt\nđồng hồ. Dòng chữ ～時～（～じ～） — giờ hiện ra giữa không khí.\nỞ kim phút, kim phút nhanh như tên lửa đuổi theo kim giờ. Mực\nkêu lên một tiếng; trên nền nhà xuất hiện ～分～（～ふん／ぷん～）\n— phút. Họ vừa đến đồng hồ cát thì đồng hồ cát chảy đúng một giờ\nrồi nổ tung. An thử đọc phù hiệu ～時間～（～じかん～） — tiếng, ～\ngiờ (thời lượng) và cảnh tượng đứng yên. Ngay bên bảng thứ hai,\nthứ Hai mặc bộ đồ mặt trăng đi qua cổng. Ánh sáng rót thành ký tự\n月曜日（げつようび） — Thứ Hai như đang chỉ đường.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Tiến thêm một bước đến bảng\nthứ ba, An bắt gặp thứ Ba đội mũ lửa nóng phừng phừng. Phù hiệu\nvừa thức dậy mang tên 火曜日（かようび） — Thứ Ba. Khi ngang qua\nbảng thứ tư, thứ Tư đổ nước làm ngập cả bàn. Những nét mực tự\nsắp thành 水曜日（すいようび） — Thứ Tư; An lập tức ghi nhớ cảnh\n\n\n                                    50","ấy. Không kịp gọi Mực, An thấy ở bảng thứ năm thứ Năm hóa\nthành cây gỗ cao. Tiếng Nhật vang lên từ chính vật ấy:\n木曜日（もくようび） — Thứ Năm. Dưới ánh đèn nơi bảng thứ sáu,\nthứ Sáu tung đồng tiền vàng khắp đường. Một dòng chữ khác phát\nsáng: 金曜日（きんようび） — Thứ Sáu.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Chạm vào bảng thứ bảy, An bỗng\nnhìn thấy thứ Bảy mọc cây mầm từ nền đất. Dòng chữ\n土曜日（どようび） — Thứ Bảy hiện ra giữa không khí. Ở bảng chủ\nnhật, Chủ Nhật phát sáng như mặt trời. Mực kêu lên một tiếng;\ntrên nền nhà xuất hiện 日曜日（にちようび） — Chủ Nhật. Họ vừa\nđến ghế nghỉ thì người mệt nằm nghỉ trên chiếc ghế dài. An thử\nđọc phù hiệu 休み（やすみ） — Nghỉ; ngày nghỉ và cảnh tượng đứng\nyên. Ngay bên chuông nghỉ trưa, chuông nghỉ trưa gọi cả đội về ăn\ncơm. Ánh sáng rót thành ký tự 昼休み（ひるやすみ） — Giờ nghỉ trưa\nnhư đang chỉ đường.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Tiến thêm một bước đến lịch\ntháng, An bắt gặp 12 tờ lịch tháng bay thành một con rồng. Phù\nhiệu vừa thức dậy mang tên ～月（がつ） — Tháng ～. Khi ngang\nqua lịch ngày, 31 ô ngày nhảy lò cò trên mặt lịch. Những nét mực\ntự sắp thành ～日（にち） — Ngày ～; An lập tức ghi nhớ cảnh ấy.\nKhông kịp gọi Mực, An thấy ở sợi dây tuần dây tuần dài quấn\nquanh tháp đồng hồ. Tiếng Nhật vang lên từ chính vật ấy:\n～週間～（～しゅうかん～） — tuần. Dưới ánh đèn nơi cột mốc năm,\nchiếc cột mốc năm già đi trong một giây. Một dòng chữ khác phát\nsáng: ～年～（～ねん～） — năm.\n\n\n\n\n                               51","Tiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Chạm vào nửa bánh, An\nbỗng nhìn thấy chiếc bánh bị chẻ đúng một nửa. Dòng chữ\n半（はん） — Một nửa; rưỡi hiện ra giữa không khí. Ở ghế đơn, một\nngười ngồi trên chiếc ghế đơn cô độc. Mực kêu lên một tiếng; trên\nnền nhà xuất hiện 一人（ひとり） — Một người. Họ vừa đến ghế đôi\nthì hai người ôm nhau trên ghế đôi. An thử đọc phù hiệu\n二人（ふたり） — Hai người và cảnh tượng đứng yên. Ngay bên tập\ngiấy mỏng, chiếc máy in phun vô số tờ giấy mỏng. Ánh sáng rót\nthành ký tự ～枚～（～まい～） — tờ, chiếc (vật mỏng, phẳng) như\nđang chỉ đường.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Tiến thêm một bước đến dãy máy\nmóc, An bắt gặp đoàn xe và máy móc đều mang thẻ đếm số chiếc.\nPhù hiệu vừa thức dậy mang tên ～台～（～だい～） — chiếc (máy\nmóc, xe cộ).\n\n   Cuối đỉnh tháp, An nghe tiếng bưu tá gọi. Có một phong thư vừa\n   được gửi từ chính tương lai của cô.\n\n\n\n\n                                52","TẬ P I I I   /   CHƯƠNG 16   /   PHÙ HIỆU 321–340\n\n\n\nBưu điện gửi thư đến ngày mai\n    Thư từ chất thành núi trong bưu điện. Một bưu tá mặt giấy\n    tuyên bố: “Không bưu kiện nào được gửi nếu người gửi chưa\n    chuẩn bị xong và chưa biết mình muốn gửi toàn bộ hay chỉ\n    một phần.”\n\nAn giúp chuẩn bị một buổi tiệc kỳ quặc để đổi lấy con tem, phong\nbì và quyền gửi thư nhanh. Cả tòa nhà phát nổ vì quà sinh nhật,\ngiấy và máy bay chuyển thư.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Ở hòm thư đến,\nngười đã đến từ trước đứng trước hòm thư. Mực kêu lên một tiếng;\ntrên nền nhà xuất hiện もう（もう） — Đã, rồi; nữa. Họ vừa đến hòm\nthư đi thì người còn chưa đến đợi ở hòm thư đối diện. An thử đọc\nphù hiệu まだ（まだ） — Vẫn còn; vẫn chưa và cảnh tượng đứng yên.\nNgay bên cửa mở tiệc, cánh cửa mở tiệc đúng khoảnh khắc bắt\nđầu. Ánh sáng rót thành ký tự 始まります（はじまります） — Bắt đầu\nnhư đang chỉ đường. Có tiếng răng rắc dưới cửa kết thúc: cánh cửa\nđóng sầm để tuyên bố kết thúc. Mực dùng đuôi vẽ lên bóng tối\n終わります（おわります） — Kết thúc, xong.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Khi ngang qua xe chở đồ, vali\nhành lý nặng làm gãy cả xe đẩy. Những nét mực tự sắp thành\n荷物（にもつ） — Hành lý, đồ đạc; An lập tức ghi nhớ cảnh ấy. Không\nkịp gọi Mực, An thấy ở bàn chuẩn bị đội robot chuẩn bị khăn bàn\ntrong nháy mắt. Tiếng Nhật vang lên từ chính vật ấy:\n\n\n                                    53","準備（じゅんび） — Chuẩn bị. Dưới ánh đèn nơi tập bài nhà, bài tập\nvề nhà mọc chân chạy trốn học sinh. Một dòng chữ khác phát\nsáng: 宿題（しゅくだい） — Bài tập về nhà. Còn tại hộp cơm, hộp cơm\nbento bung thành bàn ăn Nhật. An thì thầm phù hiệu\nお弁当（おべんとう） — Cơm hộp, nghe nó hòa vào tiếng tim mình.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Ở bàn họp, cả nhóm ngồi họp\ntrong chiếc cốc trà. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n会議（かいぎ） — Cuộc họp. Họ vừa đến bàn tiệc thì bữa tiệc bắn\nconfetti khắp phòng. An thử đọc phù hiệu パーティー（パーティー）\n— Bữa tiệc và cảnh tượng đứng yên. Ngay bên bánh sinh nhật,\nchiếc bánh sinh nhật thắp cả trăm ngọn nến. Ánh sáng rót thành\nký tự 誕生日（たんじょうび） — Sinh nhật như đang chỉ đường. Có\ntiếng răng rắc dưới hộp quà: hộp quà mở ra một món quà to hơn\nhộp. Mực dùng đuôi vẽ lên bóng tối プレゼント（プレゼント） — Quà\ntặng.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Khi ngang qua quầy tem, con\ntem bám vào trán người và không chịu rời. Những nét mực tự sắp\nthành 切手（きって） — Tem; An lập tức ghi nhớ cảnh ấy. Không kịp\ngọi Mực, An thấy ở bưu thiếp bưu thiếp biến thành cánh chim đưa\nlời nhắn. Tiếng Nhật vang lên từ chính vật ấy: はがき（はがき） —\nBưu thiếp. Dưới ánh đèn nơi phong bì, phong bì khổng lồ nuốt cả\nbàn ghế. Một dòng chữ khác phát sáng: 封筒（ふうとう） — Phong bì.\nCòn tại cửa chuyển phát nhanh, thư chuyển phát nhanh chạy vượt\nxe đua. An thì thầm phù hiệu 速達（そくたつ） — Chuyển phát\nnhanh, thư gửi nhanh, nghe nó hòa vào tiếng tim mình.\n\n\n\n\n                                54","Tiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Ở máy bay chuyển thư,\nmáy bay chở thư xé gió qua trần. Mực kêu lên một tiếng; trên nền\nnhà xuất hiện 航空便（こうくうびん） — Thư/hàng gửi bằng đường\nhàng không. Họ vừa đến tàu biển chuyển thư thì thuyền gửi thư\nvượt đại dương ngay trong sàn nhà. An thử đọc phù hiệu\n船便（ふなびん） — Thư/hàng gửi bằng đường biển và cảnh tượng\nđứng yên. Ngay bên băng chuyền gửi, bưu kiện được gửi đi nhờ\nbăng      chuyền   siêu   tốc.   Ánh   sáng   rót   thành   ký   tự\n送ります（おくります） — Gửi; tiễn như đang chỉ đường. Có tiếng\nrăng rắc dưới núi hàng hóa: tất cả hàng hóa dồn thành núi cao\nchạm mây. Mực dùng đuôi vẽ lên bóng tối 全部（ぜんぶ） — Toàn bộ,\ntất cả.\n\n   Lá thư gửi đi không mang tên người nhận. Trên mặt sau chỉ có\n   một câu hỏi: “Ai đã xóa tên em gái?”\n\n\n\n\n                                  55","TẬ P I V • 6 TẬ P • 2 6 C H Ư Ơ N G\n\n\n\n\nCHIẾC CHÌA KHÓA\nLÀ MỘT CÂU HỎI\nMuốn tìm thấy, trước hết phải biết mình đang\nhỏi điều gì.\n\n\n\n\n                      四","TẬ P I V   /   CHƯƠNG 17   /   PHÙ HIỆU 341–361\n\n\n\nThám tử của mười hai câu hỏi\n   Một thám tử đội mũ hình dấu hỏi kéo An vào văn phòng. Ông\n   không chịu nói điều mình biết; thay vào đó, mọi vật trong\n   phòng tự hỏi ai, cái gì, ở đâu, khi nào, vì sao, như thế nào.\n\nNhững chiếc mũ, ô, giày và ví tiền đều là chứng cứ bị phong ấn. An\nlần theo từng nghi vấn; mỗi đáp án mở ra một ngăn kéo và thêm\nmột mảnh của bức chân dung kẻ trộm ký ức.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Ở ghế nghi phạm,\nmột bóng người bí ẩn bước ra, ai nấy hỏi AI. Mực kêu lên một\ntiếng; trên nền nhà xuất hiện 誰（だれ） — Ai. Họ vừa đến hộp bí\nẩn thì chiếc hộp mở ra dấu hỏi CÁI GÌ cao ba mét. An thử đọc phù\nhiệu 何（なん／なに） — Cái gì, gì và cảnh tượng đứng yên. Ngay bên\ncửa không tên, cánh cửa mất biển tên, mọi người hỏi Ở ĐÂU. Ánh\nsáng rót thành ký tự どこ（どこ） — Ở đâu, nơi nào như đang chỉ\nđường. Có tiếng răng rắc dưới đồng hồ kim: đồng hồ chạy loạn,\nthám tử hỏi KHI NÀO. Mực dùng đuôi vẽ lên bóng tối いつ（いつ）\n— Khi nào.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Khi ngang qua bảng cách làm,\nngười máy làm trò khó hiểu, ai cũng hỏi THẾ NÀO. Những nét mực\ntự sắp thành どう（どう） — Thế nào, như thế nào; An lập tức ghi\nnhớ cảnh ấy. Không kịp gọi Mực, An thấy ở kệ đồ phân loại rổ đồ\nchứa đủ mọi loại hình thù khác nhau. Tiếng Nhật vang lên từ\nchính vật ấy: どんな（どんな） — Như thế nào, loại nào. Dưới ánh đèn\n\n\n                                  57","nơi kính lúp lựa chọn, ba chiếc mũ đều hỏi chọn CÁI NÀO. Một\ndòng chữ khác phát sáng: どの（どの） — Cái nào, ... nào. Còn tại hai\ncánh cửa, hai cánh cửa đỏ xanh hỏi BÊN NÀO. An thì thầm phù\nhiệu どちら（どちら） — Phía nào; cái nào trong hai cái, nghe nó hòa\nvào tiếng tim mình.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Ở máy tính tiền, máy tính tiền hét\nBAO NHIÊU TIỀN. Mực kêu lên một tiếng; trên nền nhà xuất hiện\nいくら（いくら） — Bao nhiêu tiền. Họ vừa đến bình đếm thì bình\nđếm nhân lên vô hạn, hỏi BAO NHIÊU CÁI. An thử đọc phù hiệu\nいくつ（いくつ） — Bao nhiêu cái; bao nhiêu tuổi và cảnh tượng đứng\nyên. Ngay bên thước đo, chiếc thước đo dài tận chân trời hỏi BAO\nLÂU. Ánh sáng rót thành ký tự どのくらい（どのくらい） — Khoảng\nbao nhiêu, mức độ bao nhiêu như đang chỉ đường. Có tiếng răng rắc\ndưới bảng nguyên nhân: bảng hiện chữ TẠI SAO bằng ngọn lửa.\nMực dùng đuôi vẽ lên bóng tối どうして（どうして） — Tại sao, vì\nsao.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Khi ngang qua tủ nhiều ngăn,\ncả trăm màu sắc và loại đồ vật đổ ra từ tủ. Những nét mực tự sắp\nthành いろいろ「な」（いろいろ） — Nhiều loại, đa dạng; An lập tức\nghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở tòa nhà mô hình\ntòa nhà cao 100 tầng đứng trên que tăm. Tiếng Nhật vang lên từ\nchính vật ấy: 建物（たてもの） — Tòa nhà, công trình. Dưới ánh đèn\nnơi giỏ ô, chiếc ô che cả mặt trăng khi trời mưa. Một dòng chữ\nkhác phát sáng: 傘（かさ） — Ô, dù. Còn tại tủ giày, đôi giày tự buộc\ndây rồi chạy mất. An thì thầm phù hiệu 靴（くつ） — Giày, nghe nó\nhòa vào tiếng tim mình.\n\n\n\n\n                               58","Tiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Ở ví tiền, ví tiền phóng\nra đồng xu xoay như bão. Mực kêu lên một tiếng; trên nền nhà\nxuất hiện 財布（さいふ） — Ví tiền. Họ vừa đến đồng hồ đeo thì\nđồng hồ đeo tay biến thành đồng hồ quả lắc. An thử đọc phù hiệu\n時計（とけい） — Đồng hồ và cảnh tượng đứng yên. Ngay bên giá\nkính, cặp kính mắt phóng đại con kiến thành voi. Ánh sáng rót\nthành ký tự 眼鏡（めがね） — Kính mắt như đang chỉ đường. Có\ntiếng răng rắc dưới mũ thám tử: chiếc mũ bay lên biến thành chiếc\nnấm khổng lồ. Mực dùng đuôi vẽ lên bóng tối 帽子（ぼうし） — Mũ,\nnón.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Khi ngang qua cà vạt, cà vạt quấn\nquanh thám tử như rắn. Những nét mực tự sắp thành\nネクタイ（ネクタイ） — Cà vạt; An lập tức ghi nhớ cảnh ấy.\n\n  Bức chân dung chỉ có một khoảng trắng ngay giữa khuôn mặt.\n  Thám tử thì thầm: “Kẻ ấy ở chợ Vô Danh.”\n\n\n\n\n                                59","TẬ P I V   /   CHƯƠNG 18   /   PHÙ HIỆU 362–382\n\n\n\nNgôi chợ bán những thứ\nkhông ai nhìn thấy\n   Ở chợ Vô Danh, người bán gọi một vật là “cái gì đó”, một\n   người là “ai đó”, một con đường là “đâu đó”. Kẻ lạ mặt trong\n   bóng tối cố xóa luôn cả những từ chỉ người, vật và nơi chốn.\n\nAn phải đi hết các cổng có và không, cổng bất cứ ai hay bất cứ đâu,\nrồi tìm chiếc chìa khóa giữa hàng ngàn món đồ. Mực nhận ra thứ\nbị đánh cắp không phải một người, mà là khả năng gọi tên thế giới.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Họ vừa đến hộp gì\nđó thì một món đồ gì đó lạ xuất hiện trong hộp. An thử đọc phù\nhiệu 何か（なにか） — Cái gì đó, một thứ gì đó và cảnh tượng đứng\nyên. Ngay bên bóng người, bóng ai đó đứng im nhưng không thấy\nmặt. Ánh sáng rót thành ký tự 誰か（だれか） — Ai đó như đang chỉ\nđường. Có tiếng răng rắc dưới bản đồ dấu x: mũi tên chỉ đến một\nnơi nào đó trong sương. Mực dùng đuôi vẽ lên bóng tối\nどこか（どこか） — Đâu đó, một nơi nào đó. Tiến thêm một bước đến\nlịch mờ, An bắt gặp ngày nào đó trên lịch biến thành dấu chấm\nhỏi. Phù hiệu vừa thức dậy mang tên いつか（いつか） — Một lúc\nnào đó, một ngày nào đó.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Không kịp gọi Mực, An thấy ở\nhộp trống chiếc hộp trống không có gì, kể cả không khí. Tiếng Nhật\nvang lên từ chính vật ấy: 何も（なにも） — Không gì cả. Dưới ánh\n\n\n\n                                  60","đèn nơi ghế trống, cái ghế không ai ngồi, bóng người cũng biến\nmất. Một dòng chữ khác phát sáng: 誰も（だれも） — Không ai cả.\nCòn tại ngôi làng vắng, cả thị trấn không một nơi nào mở cửa. An\nthì thầm phù hiệu どこも（どこも） — Không nơi nào cả, nghe nó hòa\nvào tiếng tim mình. Chạm vào đồng hồ vô hạn, An bỗng nhìn thấy\nđồng     hồ      cho      phép     chọn      bất    cứ    lúc    nào.   Dòng    chữ\nいつでも（いつでも） — Bất cứ khi nào, lúc nào cũng được hiện ra giữa\nkhông khí.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Họ vừa đến cánh cổng dịch\nchuyển thì cánh cổng mở được tới bất kỳ nơi đâu. An thử đọc phù\nhiệu どこでも（どこでも） — Bất cứ đâu, ở đâu cũng và cảnh tượng\nđứng yên. Ngay bên biển mọi người, mọi người đều có thể vào,\nchẳng ai bị ngăn. Ánh sáng rót thành ký tự 誰でも（だれでも） — Bất\ncứ ai, ai cũng như đang chỉ đường. Có tiếng răng rắc dưới kệ vạn\nvật: kệ chứa bất cứ món đồ nào người ta muốn. Mực dùng đuôi vẽ\nlên bóng tối 何でも（なんでも） — Bất cứ thứ gì, cái gì cũng. Tiến thêm\nmột bước đến cân hai phía, An bắt gặp hai cái cân cùng sáng lên vì\ncả     hai    đều      đúng.     Phù    hiệu       vừa    thức    dậy   mang    tên\nどちらも（どちらも） — Cả hai, bên nào cũng.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Không kịp gọi Mực, An thấy ở\nquầy tìm kiếm thám tử tìm kính lúp giữa hàng nghìn đồ. Tiếng\nNhật vang lên từ chính vật ấy: 探します（さがします） — Tìm, tìm\nkiếm. Dưới ánh đèn nơi kệ đồ vừa tìm, một chiếc chìa khóa tìm\nthấy     trong      bụi    vàng.       Một    dòng       chữ     khác   phát   sáng:\n見つけます（みつけます） — Tìm thấy, phát hiện. Còn tại quả địa cầu,\nquả địa cầu quay như chong chóng. An thì thầm phù hiệu\n世界（せかい） — Thế giới, nghe nó hòa vào tiếng tim mình. Chạm\n\n\n\n                                             61","vào quốc kỳ, An bỗng nhìn thấy một quốc gia mọc lên từ lá cờ tí\nhon. Dòng chữ 国（くに） — Đất nước, quốc gia hiện ra giữa không\nkhí.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Họ vừa đến cổng xuất\nngoại thì con tàu chở khách đi ra nước ngoài. An thử đọc phù hiệu\n外国（がいこく） — Nước ngoài và cảnh tượng đứng yên. Ngay bên\nngười ngoại quốc, người nước ngoài nói chuyện với chú mèo. Ánh\nsáng rót thành ký tự 外国人（がいこくじん） — Người nước ngoài như\nđang chỉ đường. Có tiếng răng rắc dưới bảng ngôn ngữ: các từ ngữ\nbay như bướm khỏi bảng chữ. Mực dùng đuôi vẽ lên bóng tối\n言葉（ことば） — Từ, lời nói; ngôn ngữ. Tiến thêm một bước đến cửa\nhàng, An bắt gặp cửa hàng tràn hàng hóa ra tận phố. Phù hiệu vừa\nthức dậy mang tên 店（みせ） — Cửa hàng, quán.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Không kịp gọi Mực, An thấy ở quán\ncà phê quán cà phê tỏa hương kéo mọi người vào. Tiếng Nhật vang\nlên từ chính vật ấy: 喫茶店（きっさてん） — Quán cà phê, quán giải\nkhát.\n\n  Họ tìm thấy chìa khóa cùng một lá cờ lạ. Nó hướng về tiệm quà,\n  nơi những món đồ chỉ mở được khi có người biết cho và nhận.\n\n\n\n\n                               62","TẬ P V • 6 TẬ P • 2 6 C H Ư Ơ N G\n\n\n\n\nĐIỀU MÌNH MUỐN\nGIỮ LẠI\nCho, nhận, ước mơ và những người mình yêu\nthương.\n\n\n\n\n                     五","TẬ P V   /   CHƯƠNG 19   /   PHÙ HIỆU 383–403\n\n\n\nTiệm quà nơi lòng tốt có hình\ndạng\n  Tiệm quà treo ba chiếc chuông: chuông tặng đi, chuông được\n  nhận và chuông người khác tặng mình. An bối rối vì mỗi\n  chiếc kêu một âm khác nhau.\n\nMột ông cụ bảo muốn cứu thành phố, An phải học phân biệt\nnhững bàn tay: ai trao, ai nhận, ai cho mượn, ai đi mượn. Những\nmón quà từ hoa đến cà vạt lần lượt hóa thành sinh vật sống.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Ngay bên bàn\ntặng quà, một đôi tay đưa quà cho người bên cạnh. Ánh sáng rót\nthành ký tự あげます（あげます） — Cho, tặng (mình/người phía mình\ncho người khác) như đang chỉ đường. Có tiếng răng rắc dưới hộp\nquà nhận: món quà từ ai đó bay vào tay mình. Mực dùng đuôi vẽ\nlên bóng tối もらいます（もらいます） — Nhận, được nhận. Tiến thêm\nmột bước đến hòm thư yêu thương, An bắt gặp người bạn mang\nquà tặng cho mình từ trên trời. Phù hiệu vừa thức dậy mang tên\nくれます（くれます） — Cho, tặng (ai đó cho mình/người phía mình).\nKhi ngang qua quầy cho mượn, con gấu cho bạn mượn chiếc bút\nvàng. Những nét mực tự sắp thành 貸します（かします） — Cho\nmượn; An lập tức ghi nhớ cảnh ấy.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Dưới ánh đèn nơi quầy đi\nmượn, con thỏ mượn sách và ôm khư khư không rời. Một dòng\n\n\n\n                                 64","chữ khác phát sáng: 借ります（かります） — Mượn, vay. Còn tại bàn\nchỉ dẫn, người thầy chỉ đường bằng tia laser. An thì thầm phù hiệu\n教えます（おしえます） — Dạy; chỉ, cho biết, nghe nó hòa vào tiếng\ntim mình. Chạm vào bàn học thêm, An bỗng nhìn thấy giáo viên\ntruyền   chữ   vào   đầu    học        trò   qua   phễu.   Dòng   chữ\n習います（ならいます） — Học, được dạy hiện ra giữa không khí. Ở\nvali bưu kiện, hành lý bay vào vali khổng lồ. Mực kêu lên một\ntiếng; trên nền nhà xuất hiện 荷物（にもつ） — Hành lý; hàng, bưu\nkiện.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Ngay bên máy đếm tiền, máy đếm\nphun cả núi đồng tiền. Ánh sáng rót thành ký tự お金（おかね） —\nTiền như đang chỉ đường. Có tiếng răng rắc dưới kệ tem: con tem\nchạy lên bức thư rồi dính chặt. Mực dùng đuôi vẽ lên bóng tối\n切手（きって） — Tem. Tiến thêm một bước đến giỏ hoa, An bắt gặp\nbông hoa hóa thành pháo hoa nhiều màu. Phù hiệu vừa thức dậy\nmang tên 花（はな） — Hoa. Khi ngang qua áo sơ mi, áo sơ mi tự\nmặc vào người mẫu gỗ. Những nét mực tự sắp thành\nシャツ（シャツ） — Áo sơ mi, áo; An lập tức ghi nhớ cảnh ấy.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Dưới ánh đèn nơi khăn tay,\nkhăn tay thêu hình mặt cười biết vẫy. Một dòng chữ khác phát\nsáng: ハンカチ（ハンカチ） — Khăn tay. Còn tại cà vạt, cà vạt biến\nthành con rắn thắt nút. An thì thầm phù hiệu ネクタイ（ネクタイ）\n— Cà vạt, nghe nó hòa vào tiếng tim mình. Chạm vào hộp\nchocolate, An bỗng nhìn thấy thác sô-cô-la chảy ngập cả tủ kính.\nDòng chữ チョコレート（チョコレート） — Sô-cô-la hiện ra giữa\n\n\n\n\n                                  65","không khí. Ở quầy quà lưu niệm, quà lưu niệm mọc cánh bay về\nnhà. Mực kêu lên một tiếng; trên nền nhà xuất hiện\nお土産（おみやげ） — Quà lưu niệm, quà mang về sau chuyến đi.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Ngay bên tủ dụng cụ, bộ\ndụng cụ đa năng biến thành 100 cánh tay. Ánh sáng rót thành ký\ntự 道具（どうぐ） — Công cụ, dụng cụ như đang chỉ đường. Có tiếng\nrăng rắc dưới ghế cụ ông: cụ ông chống gậy gõ nhịp điệu. Mực\ndùng đuôi vẽ lên bóng tối おじいさん（おじいさん） — Ông; cụ ông.\nTiến thêm một bước đến ghế cụ bà, An bắt gặp cụ bà đội vương\nmiện   cười   lớn.   Phù      hiệu    vừa   thức   dậy   mang   tên\nおばあさん（おばあさん） — Bà; cụ bà. Khi ngang qua ghế chú bác,\nông chú trung niên đi giày to như tàu. Những nét mực tự sắp\nthành おじさん（おじさん） — Chú, bác trai; người đàn ông trung niên;\nAn lập tức ghi nhớ cảnh ấy.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Dưới ánh đèn nơi ghế cô dì, người\ncô đứng che ô tròn bằng một ngôi nhà. Một dòng chữ khác phát\nsáng: おばさん（おばさん） — Cô, dì, bác gái; phụ nữ trung niên.\n\n  Từ hộp sô-cô-la, một ngôi sao rơi xuống. Mực nói: “Nếu dám\n  ước, chúng ta có thể nhìn thấy tương lai.”\n\n\n\n\n                                 66","TẬ P V   /   CHƯƠNG 20   /   PHÙ HIỆU 404–423\n\n\n\nHồ điều ước và đám cưới trên\nmây\n  Một hồ nước phản chiếu mọi điều người đứng trước nó muốn\n  có hoặc muốn làm. An nhìn thấy em gái nhưng hình ảnh lập\n  tức vỡ tan; hồ đòi cô đi qua các ước mơ đời thường trước khi\n  cho nhìn sâu hơn.\n\nHọ bước qua sân chơi, ao câu cá, cổng cưới, bàn ăn và chiếc võng.\nKhát nước, đói bụng, mệt mỏi, nghỉ ngơi — mỗi cảm giác kéo An\ngần hơn với đời sống mình từng có.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Có tiếng răng rắc\ndưới đài phun điều ước: ngôi sao điều ước hiện lên một món đồ\nmuốn có. Mực dùng đuôi vẽ lên bóng tối 欲しい（ほしい） — Muốn\ncó. Tiến thêm một bước đến cầu nguyện, An bắt gặp biển MUỐN\nLÀM hiện ra rồi đôi chân tự nhảy. Phù hiệu vừa thức dậy mang tên\n～たいです（～たいです） — Muốn làm ～. Khi ngang qua sân chơi,\nđám trẻ chơi xích đu đến tận mây. Những nét mực tự sắp thành\n遊びます（あそびます） — Chơi, vui chơi; An lập tức ghi nhớ cảnh ấy.\nKhông kịp gọi Mực, An thấy ở ao câu cá con cá kéo cần câu và kéo\ncả người xuống nước. Tiếng Nhật vang lên từ chính vật ấy:\n釣りをします（つりをします） — Câu cá.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Còn tại cổng đám cưới, cô dâu\nchú rể cưỡi xe hoa khổng lồ. An thì thầm phù hiệu\n\n\n\n                                 67","結婚します（けっこんします） — Kết hôn, nghe nó hòa vào tiếng tim\nmình. Chạm vào bàn ăn, An bỗng nhìn thấy tiệc ăn uống dài đến\ntận chân trời. Dòng chữ 食事します（しょくじします） — Dùng bữa,\năn uống hiện ra giữa không khí. Ở máy nước khát, người khát ôm\nbình nước lớn hơn người. Mực kêu lên một tiếng; trên nền nhà\nxuất hiện 喉が渇きます（のどがかわきます） — Khát nước. Họ vừa\nđến tủ đồ đói thì bụng đói kêu như loa phóng thanh. An thử đọc\nphù hiệu お腹が空きます（おなかがすきます） — Đói bụng và cảnh\ntượng đứng yên.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Có tiếng răng rắc dưới ghế mỏi:\nngười mệt rũ xuống thành đống mì. Mực dùng đuôi vẽ lên bóng tối\n疲れます（つかれます） — Mệt, mệt mỏi. Tiến thêm một bước đến\nvõng nghỉ, An bắt gặp võng chở người đang nghỉ và tự đung đưa.\nPhù hiệu vừa thức dậy mang tên 休みます（やすみます） — Nghỉ,\nnghỉ ngơi. Khi ngang qua giường lười, người lười nằm khểnh xem\nmây     bay.      Những     nét        mực   tự    sắp     thành\nゆっくりします（ゆっくりします） — Thong thả, nghỉ ngơi thoải mái;\nAn lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở gương\ngiấc mơ giấc mơ biến thành cửa dẫn tới lâu đài. Tiếng Nhật vang\nlên từ chính vật ấy: 夢（ゆめ） — Ước mơ; giấc mơ.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Còn tại cỗ máy tương lai, cỗ\nmáy đưa người tới tương lai trong nháy mắt. An thì thầm phù hiệu\n将来（しょうらい） — Tương lai, sau này, nghe nó hòa vào tiếng tim\nmình. Chạm vào cổng cuối tuần, An bỗng nhìn thấy biển cuối tuần\nlàm cả công viên bắn pháo hoa. Dòng chữ 週末（しゅうまつ） —\nCuối tuần hiện ra giữa không khí. Ở bãi nghỉ hè, mùa hè nắng nóng\nrực, kỳ nghỉ dài vô tận. Mực kêu lên một tiếng; trên nền nhà xuất\n\n\n\n                                  68","hiện 夏休み（なつやすみ） — Kỳ nghỉ hè. Họ vừa đến bãi nghỉ đông\nthì mùa đông tuyết phủ đầy bãi cỏ nghỉ dưỡng. An thử đọc phù\nhiệu 冬休み（ふゆやすみ） — Kỳ nghỉ đông và cảnh tượng đứng yên.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Có tiếng răng rắc dưới\nđường đi đâu đó: mũi tên đưa đến đâu đó nhưng không ghi địa chỉ.\nMực dùng đuôi vẽ lên bóng tối どこか（どこか） — Đâu đó, nơi nào\nđó. Tiến thêm một bước đến hộp bí mật, An bắt gặp một cái gì đó bí\nẩn đang nảy trong hộp. Phù hiệu vừa thức dậy mang tên\n何か（なにか） — Cái gì đó. Khi ngang qua đồng hồ khoảng giờ, kim\nđồng hồ dừng vào khoảng giờ bất kỳ. Những nét mực tự sắp thành\n～ごろ（～ごろ） — Khoảng ～ (thời điểm); An lập tức ghi nhớ cảnh\nấy. Không kịp gọi Mực, An thấy ở sàn nằm dài cả đội lăn qua lăn lại\ntrên sàn như những khúc gỗ. Tiếng Nhật vang lên từ chính vật ấy:\nごろごろします（ごろごろします） — Nằm khểnh, lười biếng nghỉ ở nhà.\n\n  Ở cuối giấc mơ, An thấy chiếc giường bệnh. Tương lai gửi đến\n  một lời nhắn: “Đừng bỏ quên cuộc hẹn quan trọng.”\n\n\n\n\n                                69","TẬ P V   /   CHƯƠNG 21   /   PHÙ HIỆU 424–443\n\n\n\nPhòng khám của những lời\nhứa\n  Bác sĩ trong căn phòng trắng không khám bằng ống nghe mà\n  bằng lời giải thích. Mỗi bệnh nhân phải kể lý do mình đến,\n  việc cần làm và lời hứa mình chưa hoàn thành.\n\nAn đi qua một chuỗi cảnh bệnh tật và những khoảng cách bị kéo\ngiãn kỳ lạ. Một con đường quá gần lại dẫn đến căn phòng rất xa;\nmột căn phòng chật lại giấu cả hội trường rộng.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Có tiếng răng rắc\ndưới biển nguyên nhân: tấm bảng VÌ THẾ kéo theo cả đoàn người.\nMực dùng đuôi vẽ lên bóng tối ですから（ですから） — Vì thế, do đó.\nTiến thêm một bước đến quầy xin lỗi, An bắt gặp người xin lỗi rồi\ntiếc nuối, nước mắt rơi thành đá. Phù hiệu vừa thức dậy mang tên\n残念です（ざんねんです） — Đáng tiếc, thật tiếc. Khi ngang qua phòng\ncảm cúm, virus cúm nhảy ra từ chiếc khăn giấy. Những nét mực tự\nsắp thành 風邪を引きます（かぜをひきます） — Bị cảm, cảm lạnh; An\nlập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở ghế ho cơn\nho vang như tiếng trống lớn. Tiếng Nhật vang lên từ chính vật ấy:\n咳が出ます（せきがでます） — Bị ho, có triệu chứng ho.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Còn tại máy đo đau đầu, đầu\nđau đến mức có chiếc búa gõ cồm cộp. An thì thầm phù hiệu\n頭が痛いです（あたまがいたいです） — Đau đầu, nghe nó hòa vào\n\n\n\n                                 70","tiếng tim mình. Chạm vào máy đo đau bụng, An bỗng nhìn thấy\nbụng   đau   và     quặn   như    bị    con    rắn    siết.    Dòng   chữ\nお腹が痛いです（おなかがいたいです） — Đau bụng hiện ra giữa\nkhông khí. Ở nhiệt kế sốt, nhiệt kế nhảy vọt lên 40 độ đỏ rực. Mực\nkêu    lên    một     tiếng;     trên    nền         nhà      xuất    hiện\n熱があります（ねつがあります） — Bị sốt. Họ vừa đến băng cứu\nthương thì cánh tay bị thương quấn băng trắng như xác ướp. An\nthử đọc phù hiệu 怪我をします（けがをします） — Bị thương, bị chấn\nthương và cảnh tượng đứng yên.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Có tiếng răng rắc dưới quầy chúc\nkhỏe: bác sĩ cúi đầu chúc mau khỏe. Mực dùng đuôi vẽ lên bóng tối\nお大事に（おだいじに） — Chúc mau khỏe, giữ gìn sức khỏe nhé. Tiến\nthêm một bước đến giường buồn ngủ, An bắt gặp chiếc gối dụ\nngười ngái ngủ nằm xuống. Phù hiệu vừa thức dậy mang tên\n眠い（ねむい） — Buồn ngủ. Khi ngang qua gánh nặng khổng lồ, một\ntảng đá cực nặng gây đủ chuyện vất vả. Những nét mực tự sắp\nthành 大変「な」（たいへん） — Vất vả, khó khăn; nghiêm trọng; An\nlập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở con đường\ngần con đường gần chỉ ba bước chân. Tiếng Nhật vang lên từ chính\nvật ấy: 近い（ちかい） — Gần.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Còn tại con đường xa, con\nđường xa kéo tận chân trời. An thì thầm phù hiệu 遠い（とおい） —\nXa, nghe nó hòa vào tiếng tim mình. Chạm vào phòng nhỏ, An\nbỗng nhìn thấy phòng bé xíu ép người thành hình vuông. Dòng\nchữ 狭い（せまい） — Hẹp, chật hiện ra giữa không khí. Ở hội\ntrường rộng, hội trường rộng nở thành sân vận động. Mực kêu lên\nmột tiếng; trên nền nhà xuất hiện 広い（ひろい） — Rộng, rộng rãi.\n\n\n\n                                  71","Họ vừa đến cửa nguy hiểm thì biển cảnh báo nổ pháo nguy hiểm\nđỏ chói. An thử đọc phù hiệu 危ない（あぶない） — Nguy hiểm và\ncảnh tượng đứng yên.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Có tiếng răng rắc dưới\nbảng lý do: thám tử lần theo hàng nghìn lý do. Mực dùng đuôi vẽ\nlên bóng tối 理由（りゆう） — Lý do. Tiến thêm một bước đến bàn\nviệc riêng, An bắt gặp việc riêng hiện thành chiếc va-li niêm\nphong. Phù hiệu vừa thức dậy mang tên 用事（ようじ） — Việc cần\nlàm, việc riêng. Khi ngang qua sổ hẹn, sổ hẹn khóa người vào cuộc\nhẹn có giờ. Những nét mực tự sắp thành 約束（やくそく） — Lời\nhứa; cuộc hẹn; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An\nthấy ở quầy làm thêm bảng tuyển việc làm thêm mọc chân đi tìm\nnhân   viên.   Tiếng   Nhật   vang   lên   từ   chính   vật   ấy:\nアルバイト（アルバイト） — Việc làm thêm.\n\n  Nhờ giữ được lời hứa, An rời bệnh viện với tấm gương phản\n  chiếu gương mặt thật của kẻ trộm: một người không có ký ức về\n  bản thân.\n\n\n\n\n                               72","TẬ P V   /   CHƯƠNG 22   /   PHÙ HIỆU 444–463\n\n\n\nPhố mặt nạ và những tên gọi\nthân thương\n  Mọi người trên phố đều đeo mặt nạ. Một người chỉ hiện rõ\n  mặt khi được gọi đúng mối quan hệ, tên thân mật, hoặc nhận\n  ra chiếc áo, đôi giày, cặp kính mình đang mang.\n\nAn đi qua cửa hàng thời trang, tưởng mình chỉ thay quần áo,\nnhưng mỗi bộ phận cơ thể lại nhắc cô về người em gái. “Trí nhớ,”\nMực nói, “không chỉ nằm trong đầu; nó còn nằm trong cách ta gọi\nnhau.”\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Có tiếng răng rắc\ndưới tủ áo: áo khoác tự chạy đến mặc lên vai người. Mực dùng\nđuôi vẽ lên bóng tối 着ます（きます） — Mặc (áo, áo khoác, váy liền...).\nTiến thêm một bước đến kệ quần giày, An bắt gặp quần và giày tự\nchui     vào   chân.   Phù   hiệu     vừa   thức   dậy   mang   tên\n履きます（はきます） — Mặc, đi (quần, váy, giày, tất...). Khi ngang qua\nmóc mũ, chiếc mũ khổng lồ úp xuống đầu như cái chậu. Những\nnét mực tự sắp thành 被ります（かぶります） — Đội, trùm; An lập tức\nghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở gương kính đôi\nkính mắt phóng đại mọi thứ gấp nghìn lần. Tiếng Nhật vang lên từ\nchính vật ấy: 眼鏡をかけます（めがねをかけます） — Đeo kính.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Còn tại ảnh em bé, em bé mới\nsinh bay xuống trong chiếc nôi trăng. An thì thầm phù hiệu\n\n\n\n                                 73","生まれます（うまれます） — Được sinh ra, ra đời, nghe nó hòa vào\ntiếng tim mình. Chạm vào thước đo chiều cao, An bỗng nhìn thấy\ncây thước kéo người cao thẳng tới trần nhà. Dòng chữ\n背が高い（せがたかい） — Cao, có vóc dáng cao hiện ra giữa không\nkhí. Ở thước đo chiều thấp, thước khác ép người lùn xuống bằng\ncây nấm. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n背が低い（せがひくい） — Thấp, có vóc dáng thấp. Họ vừa đến tròng\nmắt thì một đôi mắt đảo quanh nhìn 360 độ. An thử đọc phù hiệu\n目（め） — Mắt và cảnh tượng đứng yên.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Có tiếng răng rắc dưới tai nghe:\nhai tai to như cánh quạt nghe tiếng ruồi. Mực dùng đuôi vẽ lên\nbóng tối 耳（みみ） — Tai. Tiến thêm một bước đến mũi giả, An bắt\ngặp mũi cao phun hương thơm thành cầu vồng. Phù hiệu vừa thức\ndậy mang tên 鼻（はな） — Mũi. Khi ngang qua miệng cười, cái\nmiệng rộng bằng cánh cửa cười toe. Những nét mực tự sắp thành\n口（くち） — Miệng; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực,\nAn thấy ở hàm răng răng trắng phát sáng như đèn pha. Tiếng Nhật\nvang lên từ chính vật ấy: 歯（は） — Răng.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Còn tại mái tóc giả, mái tóc mọc\nnhanh    thành   một    khu   rừng.   An   thì   thầm   phù    hiệu\n髪の毛（かみのけ） — Tóc, nghe nó hòa vào tiếng tim mình. Chạm\nvào gương mặt, An bỗng nhìn thấy khuôn mặt lăn ra khỏi tấm\ngương như quả bóng. Dòng chữ 顔（かお） — Khuôn mặt hiện ra\ngiữa không khí. Ở tượng cơ thể, cơ thể người máy tháo rời từng bộ\nphận. Mực kêu lên một tiếng; trên nền nhà xuất hiện 体（からだ）\n\n\n\n\n                                 74","— Cơ thể. Họ vừa đến khách vip thì vị khách quý được trải thảm đỏ\nbước vào. An thử đọc phù hiệu 方（かた） — Vị, người (cách nói lịch\nsự của 人) và cảnh tượng đứng yên.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Có tiếng răng rắc dưới\nthẻ cậu bé: thẻ tên CẬU xuất hiện trên áo cậu bé. Mực dùng đuôi\nvẽ lên bóng tối ～くん（～くん） — Cậu, em... (cách gọi thân mật). Tiến\nthêm một bước đến búp bê bé gái, An bắt gặp búp bê nhỏ được gọi\nthân mật bằng giọng ngân nga. Phù hiệu vừa thức dậy mang tên\n～ちゃん（～ちゃん） — Bé, em... (cách gọi thân mật). Khi ngang qua\nnhẫn độc thân, người độc thân đứng một mình với nhẫn trống.\nNhững nét mực tự sắp thành 独身（どくしん） — Độc thân, chưa kết\nhôn; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở\nbảng tôi biết một con cú cầm biển TÔI BIẾT và gật liên tục. Tiếng\nNhật vang lên từ chính vật ấy: 知っています（しっています） — Biết,\nđang biết.\n\n   Sau lớp mặt nạ cuối cùng, An nhìn thấy gương mặt của chính\n   mình khi còn nhỏ. Chiếc chìa khóa dẫn vào xưởng sáng tạo.\n\n\n\n\n                               75","TẬ P V I • 6 TẬ P • 2 6 C H Ư Ơ N G\n\n\n\n\nTIẾNG CHUÔNG\nCUỐI CÙNG\nMột ký ức được cứu khi nó có thể trở thành lời\nnói.\n\n\n\n\n                      六","TẬ P V I    /    CHƯƠNG 23      /   PHÙ HIỆU 464–484\n\n\n\nXưởng tranh giữ lại tiếng hát\n   Xưởng sáng tạo chứa tranh chưa vẽ, những bản nhạc chưa\n   chơi và các trang nhật ký chưa viết. Trên bàn là chiếc hộp\n   mang tên An, nhưng bên trong chỉ có một tờ giấy ghi: “Hãy\n   nhớ điều mình thích.”\n\nMực gợi An vẽ, chơi nhạc, sưu tầm và viết lại từng kỷ niệm; những\nâm thanh jazz và cổ điển tràn ra thành các dòng chữ Nhật. Chậm\nvà nhanh, giỏi và dở, mọi trải nghiệm đều có chỗ đứng.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Có tiếng răng rắc\ndưới giá vẽ: bút lông tự vẽ cả bức tường thành tranh khổng lồ.\nMực dùng đuôi vẽ lên bóng tối 描きます（かきます） — Vẽ. Tiến\nthêm một bước đến đàn piano, An bắt gặp đàn piano bật chân tự\nchơi       nốt    nhạc.   Phù       hiệu        vừa   thức   dậy   mang   tên\n弾きます（ひきます） — Chơi, đánh đàn. Khi ngang qua tủ sưu tầm,\nngười sưu tầm hứng sao trời vào bình thủy tinh. Những nét mực\ntự sắp thành 集めます（あつめます） — Thu thập, sưu tầm; An lập tức\nghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở bàn đổi đồ máy đổi\nmón cũ lấy món khác bằng tia sáng. Tiếng Nhật vang lên từ chính\nvật ấy: 換えます（かえます） — Đổi, đổi sang thứ khác.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Còn tại sổ ghi nhớ, bộ não\nnuốt từ vựng và ghi nhớ lên kính. An thì thầm phù hiệu\n覚えます（おぼえます） — Nhớ, ghi nhớ; học thuộc, nghe nó hòa vào\ntiếng tim mình. Chạm vào tẩy xóa ký ức, An bỗng nhìn thấy cục tẩy\n\n\n                                           77","xóa sạch mọi ký ức trên bảng. Dòng chữ 忘れます（わすれます） —\nQuên hiện ra giữa không khí. Ở bảng sở thích, sở thích biến thành\ncông viên đồ chơi mini. Mực kêu lên một tiếng; trên nền nhà xuất\nhiện 趣味（しゅみ） — Sở thích. Họ vừa đến khung tranh thì bức\ntranh mở cửa cho nhân vật chạy ra. An thử đọc phù hiệu 絵（え）\n— Tranh, bức tranh và cảnh tượng đứng yên.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Có tiếng răng rắc dưới dàn loa: âm\nnhạc rung làm cả sàn nhà nhảy múa. Mực dùng đuôi vẽ lên bóng\ntối 音楽（おんがく） — Âm nhạc. Tiến thêm một bước đến máy nhạc\ncổ điển, An bắt gặp nhạc cổ điển gọi một dàn nhạc mặc tuxedo.\nPhù hiệu vừa thức dậy mang tên クラシック（クラシック） — Nhạc\ncổ điển. Khi ngang qua đĩa jazz, nhạc jazz gọi chiếc kèn saxophone\nmàu vàng. Những nét mực tự sắp thành ジャズ（ジャズ） — Nhạc\nJazz; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở sân\nhòa nhạc cả buổi hòa nhạc bùng sáng với khán giả hò reo. Tiếng\nNhật vang lên từ chính vật ấy: コンサート（コンサート） — Buổi hòa\nnhạc, buổi biểu diễn.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Còn tại mic karaoke, mic\nkaraoke hát vang làm kính nứt. An thì thầm phù hiệu\nカラオケ（カラオケ） — Karaoke, nghe nó hòa vào tiếng tim mình.\nChạm vào bài hát, An bỗng nhìn thấy bài hát bay lên như con chim\nnhiều màu. Dòng chữ 歌（うた） — Bài hát hiện ra giữa không khí.\nỞ sàn nhảy, vũ công xoay làm sàn nhảy biến thành bão. Mực kêu\nlên một tiếng; trên nền nhà xuất hiện ダンス（ダンス） — Nhảy,\nkhiêu vũ. Họ vừa đến nhật ký thì nhật ký mở ra cho các ngày tự\nchạy ra. An thử đọc phù hiệu 日記（にっき） — Nhật ký và cảnh\ntượng đứng yên.\n\n\n\n                                78","Tiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Có tiếng răng rắc dưới bộ\nthẻ: các thẻ bài biết đánh nhau như nhân vật hoạt hình. Mực dùng\nđuôi vẽ lên bóng tối カード（カード） — Thẻ, card. Tiến thêm một\nbước đến máy internet, An bắt gặp mạng internet kéo sợi dây\nxuyên khắp trái đất. Phù hiệu vừa thức dậy mang tên\nインターネット（インターネット） — Internet. Khi ngang qua cúp\nngười giỏi, người giỏi nhận cúp vàng to hơn đầu. Những nét mực\ntự sắp thành 上手「な」（じょうず） — Giỏi, khéo; An lập tức ghi\nnhớ cảnh ấy. Không kịp gọi Mực, An thấy ở bảng người kém người\nkém chơi đàn khiến micro bỏ chạy. Tiếng Nhật vang lên từ chính\nvật ấy: 下手「な」（へた） — Kém, dở, không giỏi.\n\n\nMực im lặng một lúc lâu. An hiểu: chỉ còn vài phù hiệu nữa trước\nkhi cánh cửa cuối cùng mở ra. Còn tại đồng hồ tốc độ, vận động\nviên chạy nhanh như tia chớp. An thì thầm phù hiệu\n速い（はやい） — Nhanh, nghe nó hòa vào tiếng tim mình.\n\n  Bức tranh hoàn thành cho thấy em gái đang đứng trước một\n  màn hình tivi lớn. An nhận ra cuộc đối đầu cuối cùng đã bắt\n  đầu.\n\n\n\n\n                                79","TẬ P V I   /   CHƯƠNG 24   /   PHÙ HIỆU 485–508\n\n\n\nĐài truyền hình phát toàn tin\ngiả\n   Lão Rỗng chiếm mọi màn hình và tuyên bố: “Không ai nhớ\n   được sự thật, ta sẽ kể chuyện tùy ý.” An xông vào đài truyền\n   hình.\n\nTrong trường quay, thật và giả, thắng và thua, nghĩ và nói liên tục\nđổi chỗ. Lần đầu tiên, An phải tự quyết định.\n\nMực giật tai. Tiến thêm một bước đến ghế bình luận, An bắt gặp\nbộ não to bằng trái dưa nghĩ ra 100 ý tưởng. Phù hiệu vừa thức\ndậy mang tên 思います（おもいます） — Nghĩ, cho rằng. Khi ngang\nqua micro phát biểu, cái miệng phóng lời nói ra như pháo giấy.\nNhững nét mực tự sắp thành 言います（いいます） — Nói, nói rằng;\nAn lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở cúp\nchiến thắng cúp chiến thắng mọc cánh bay lên trời. Tiếng Nhật\nvang lên từ chính vật ấy: 勝ちます（かちます） — Thắng. Dưới ánh\nđèn nơi bảng thua, bảng thua tan chảy như kem. Một dòng chữ\nkhác phát sáng: 負けます（まけます） — Thua. Còn tại máy hữu ích,\nchiếc dụng cụ hữu ích cứu người bằng một cánh tay. An thì thầm\nphù hiệu 役に立ちます（やくにたちます） — Có ích, hữu ích, nghe nó\nhòa vào tiếng tim mình.\n\n\nBóng đèn nhấp nháy. Ở bánh răng chuyển động, máy móc chuyển\nđộng tự quay 100 vòng. Mực kêu lên một tiếng; trên nền nhà xuất\nhiện 動きます（うごきます） — Chuyển động; hoạt động, chạy (máy\nmóc). Họ vừa đến tivi thời sự thì màn hình chiếu tin tức mới nổi\n\n\n\n                                  80","như bong bóng. An thử đọc phù hiệu ニュース（ニュース） — Tin tức\nvà cảnh tượng đứng yên. Ngay bên bục chính trị, chính trị gia\ntranh luận trên chiếc bục xoay. Ánh sáng rót thành ký tự\n政治（せいじ） — Chính trị như đang chỉ đường. Có tiếng răng rắc\ndưới bảng kinh tế: biểu đồ kinh tế lên xuống như tàu lượn. Mực\ndùng đuôi vẽ lên bóng tối 経済（けいざい） — Kinh tế. Tiến thêm\nmột bước đến sân thi đấu, An bắt gặp trận đấu bóng đá diễn ra\ntrên một chiếc bàn. Phù hiệu vừa thức dậy mang tên 試合（しあい）\n— Trận đấu.\n\n\nAn nghe tiếng bước chân. Không kịp gọi Mực, An thấy ở bảng ý\nkiến tiếng nói Ý KIẾN mọc miệng khắp phòng. Tiếng Nhật vang lên\ntừ chính vật ấy: 意見（いけん） — Ý kiến. Dưới ánh đèn nơi góc kể\nchuyện, người kể chuyện bước ra từ quyển sách. Một dòng chữ\nkhác phát sáng: お話（おはなし） — Câu chuyện; lời nói, chuyện. Còn\ntại mặt nạ nói dối, kẻ nói dối có mũi dài ra như Pinocchio. An thì\nthầm phù hiệu 嘘（うそ） — Lời nói dối, nghe nó hòa vào tiếng tim\nmình. Chạm vào gương sự thật, An bỗng nhìn thấy gương sự thật\nlột hết mặt nạ ngụy trang. Dòng chữ 本当（ほんとう） — Sự thật;\nthật, thật sự hiện ra giữa không khí. Ở máy dự đoán, quả cầu thủy\ntinh dự báo CÓ LẼ. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n多分（たぶん） — Có lẽ, chắc là.\n\n\nMực nhảy lên bàn. Ngay bên máy chắc chắn, người máy chắc chắn\nđến mức đóng dấu 100 lần. Ánh sáng rót thành ký tự\nきっと（きっと） — Chắc chắn, chắc là như đang chỉ đường. Có tiếng\nrăng rắc dưới thước mức độ: đồng hồ đo mức độ nhảy lên rất cao.\nMực dùng đuôi vẽ lên bóng tối そんなに（そんなに） — Đến mức như\nthế, đến vậy. Tiến thêm một bước đến bảng chủ đề, An bắt gặp chiếc\nkính lúp soi đúng một chủ đề. Phù hiệu vừa thức dậy mang tên\n～について（～について） — Về, liên quan đến ～. Khi ngang qua ghế\n\n\n\n                                81","tất nhiên, cả phòng cùng gật đầu: TẤT NHIÊN. Những nét mực tự\nsắp thành もちろん（もちろん） — Tất nhiên, đương nhiên; An lập tức\nghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở tấm lịch lâu ngày\nbạn cũ gặp nhau sau thời gian rất lâu. Tiếng Nhật vang lên từ\nchính vật ấy: 久しぶり（ひさしぶり） — Lâu rồi, sau một thời gian dài.\n\n\nMột tiếng chuông vang lên. Còn tại phong bì bí mật, phong bì mở\nra điều THỰC RA bí mật. An thì thầm phù hiệu 実は（じつは） —\nThực ra, thật ra là, nghe nó hòa vào tiếng tim mình. Chạm vào đèn\nspotlight, An bỗng nhìn thấy đèn chiếu rọi một người ĐẶC BIỆT\ntrong đám đông. Dòng chữ 特に（とくに） — Đặc biệt, đặc biệt là hiện\nra giữa không khí. Ở cổng quay về, người cũ quay trở lại đúng như\ndự đoán. Mực kêu lên một tiếng; trên nền nhà xuất hiện\nやはり／やっぱり（やはり／やっぱり） — Quả nhiên; đúng như nghĩ;\ncuối cùng vẫn.... Họ vừa đến cờ đích thì vận động viên cuối cùng\ncũng chạm được đích. An thử đọc phù hiệu やっと（やっと） — Cuối\ncùng cũng, mãi mới và cảnh tượng đứng yên.\n\n  Đến cuối bản tin, An đọc được lời thú nhận của Lão Rỗng: hắn\n  không lấy em gái đi; hắn chỉ làm mọi người quên cách tìm về\n  nhau.\n\n\n\n\n                               82","TẬ P V I   /   CHƯƠNG 25   /   PHÙ HIỆU 509–528\n\n\n\nXưởng sửa chữa thành phố\n   Cả thành phố bỗng ngừng chuyển động. Nhà máy hỏng, đèn\n   giao thông tắt, các con đường dẫn vào ngõ cụt. An đi đến\n   xưởng sửa chữa với chiếc chìa khóa đã sáng lên sáu màu.\n\nỞ đó, những ký ức tuổi nhỏ trở thành dụng cụ: có việc khó xử, có\nlúc cô đơn, có máy hỏng cần sửa và những con đường phải băng\nqua cẩn thận. Không thể chỉ nhớ từ; An còn phải biết dùng chúng\nđể sửa thế giới.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Còn tại ảnh trẻ\ncon, ảnh trẻ con biết đi trượt ra khỏi khung. An thì thầm phù hiệu\n若い（わかい） — Trẻ, trẻ tuổi, nghe nó hòa vào tiếng tim mình.\nChạm vào sân chơi ngày xưa, An bỗng nhìn thấy tấm ảnh thời thơ\nấu nhảy múa trước mắt. Dòng chữ 子供の時（こどものとき） — Khi\ncòn nhỏ hiện ra giữa không khí. Ở nhẫn thời độc thân, nhẫn độc\nthân bay vòng quanh người đứng một mình. Mực kêu lên một\ntiếng; trên nền nhà xuất hiện 独身の時（どくしんのとき） — Khi còn\nđộc thân. Họ vừa đến ghế rảnh rỗi thì con lười rảnh nằm dài trên\nghế. An thử đọc phù hiệu 暇な時（ひまなとき） — Khi rảnh rỗi và\ncảnh tượng đứng yên.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Có tiếng răng rắc dưới máy\nbáo rắc rối: máy gặp rắc rối nổ tung ra toàn dấu chấm hỏi. Mực\ndùng đuôi vẽ lên bóng tối 困ります（こまります） — Khó xử, gặp rắc\nrối. Tiến thêm một bước đến ghế cô đơn, An bắt gặp một người cô\n\n\n\n                                  83","đơn ngồi cạnh chiếc ghế trống. Phù hiệu vừa thức dậy mang tên\n寂しい（さびしい） — Cô đơn, buồn vì vắng vẻ. Khi ngang qua máy\nhỏng, máy hỏng khạc khói đen như rồng. Những nét mực tự sắp\nthành 故障します（こしょうします） — Bị hỏng, gặp sự cố (máy móc);\nAn lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở hộp\ndụng cụ sửa thợ sửa chữa dùng búa thần làm máy sáng lại. Tiếng\nNhật vang lên từ chính vật ấy: 直します（なおします） — Sửa, sửa\nchữa.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Còn tại máy tra cứu, kính lúp tra\ncứu     từng   con   ốc     dưới   đèn.   An    thì    thầm    phù   hiệu\n調べます（しらべます） — Tìm hiểu, tra cứu, kiểm tra, nghe nó hòa vào\ntiếng tim mình. Chạm vào cầu băng qua, An bỗng nhìn thấy người\nbăng qua cây cầu chỉ bằng một bước nhảy. Dòng chữ\n渡ります（わたります） — Băng qua, đi qua hiện ra giữa không khí. Ở\nbiển cảnh báo, biển cẩn thận phun tiếng còi làm giật mình. Mực\nkêu     lên    một        tiếng;   trên   nền         nhà     xuất   hiện\n気をつけます（きをつけます） — Cẩn thận, chú ý. Họ vừa đến xe\nchuyển nhà thì xe chuyển nhà chở nguyên cả ngôi nhà đi. An thử\nđọc phù hiệu お引っ越し（おひっこし） — Việc chuyển nhà và cảnh\ntượng đứng yên.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Có tiếng răng rắc dưới kệ kích\ncỡ: cái áo tự lớn từ size S sang size XXXL. Mực dùng đuôi vẽ lên\nbóng tối サイズ（サイズ） — Kích cỡ, cỡ. Tiến thêm một bước đến loa\nâm thanh, An bắt gặp loa âm thanh biến tiếng muỗi thành sấm.\nPhù hiệu vừa thức dậy mang tên 音（おと） — Âm thanh, tiếng động.\nKhi ngang qua cỗ máy cơ khí, máy cơ khí 100 bánh răng nghiến\nrào rào. Những nét mực tự sắp thành 機械（きかい） — Máy móc,\n\n\n\n                                    84","máy; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở\nnúm vặn núm vặn xoay làm cả tòa nhà quay tròn. Tiếng Nhật vang\nlên từ chính vật ấy: つまみ（つまみ） — Núm vặn, núm điều chỉnh.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Còn tại bộ phận hỏng,\nmột cỗ máy bị sự cố nằm gục giữa xưởng. An thì thầm phù hiệu\n故障（こしょう） — Sự hỏng hóc, sự cố, nghe nó hòa vào tiếng tim\nmình. Chạm vào đường trước xưởng, An bỗng nhìn thấy con\nđường nhựa uốn ra khỏi cửa nhà máy. Dòng chữ 道（みち） —\nĐường, con đường hiện ra giữa không khí. Ở ngã tư, ngã tư sáng lên\nbốn lối đi rực rỡ. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n交差点（こうさてん） — Ngã tư, giao lộ. Họ vừa đến đèn tín hiệu thì\nđèn tín hiệu nháy đỏ vàng xanh không ngừng. An thử đọc phù\nhiệu 信号（しんごう） — Đèn giao thông, tín hiệu và cảnh tượng đứng\nyên.\n\n  Cỗ máy cuối cùng hoạt động trở lại. Lối ra mở thông tới đường\n  đua của cảm xúc, nơi Lão Rỗng đang chờ.\n\n\n\n\n                                85","TẬ P V I   /   CHƯƠNG 26   /   PHÙ HIỆU 529–545\n\n\n\nĐường đua cuối cùng: không ai\nbị lãng quên\n   Lão Rỗng mở một đường đua từ chiếc giường cũ đến trường\n   học ngày xưa của An. Hắn nói chỉ cần cô quên một điều, tất cả\n   sẽ biến mất. An đáp: “Không. Có những điều quên rồi vẫn có\n   thể tìm lại.”\n\nCô đi bộ, chạy, lái, hát, cười, khóc, suy nghĩ, mệt và buồn ngủ như\nmột con người thật. Lần này, từng dòng tiếng Nhật không còn là\nphép thuật xa lạ mà là cái tên của những điều cô đã sống.\n\nAn men theo con đường mà Mực vừa vẽ bằng đuôi. Những đồ vật\nbắt đầu trả lời bằng chính hình dạng của chúng. Còn tại vạch xuất\nphát, người đi bộ với đôi giày biết nhảy. An thì thầm phù hiệu\n歩きます（あるきます） — Đi bộ, nghe nó hòa vào tiếng tim mình.\nChạm vào làn chạy, An bỗng nhìn thấy vận động viên chạy nhanh\nđể lại vệt lửa. Dòng chữ 走ります（はしります） — Chạy hiện ra giữa\nkhông khí. Ở vô lăng, người lái xe lao vòng qua cọc tiêu. Mực kêu\nlên một tiếng; trên nền nhà xuất hiện 運転します（うんてんします）\n— Lái xe. Họ vừa đến sân hát thì ca sĩ hát, nốt nhạc rơi như mưa.\nAn thử đọc phù hiệu 歌います（うたいます） — Hát và cảnh tượng\nđứng yên.\n\n\nChiếc chìa khóa sáu màu nóng lên trong túi áo. Mực nhìn trước,\nAn ghi nhớ từng hình ảnh phía sau. Có tiếng răng rắc dưới mặt nạ\ncười: gương mặt cười toe rộng bằng mặt trăng. Mực dùng đuôi vẽ\nlên bóng tối 笑います（わらいます） — Cười. Tiến thêm một bước\n\n\n\n                                  86","đến mặt nạ khóc, An bắt gặp mắt khóc ra những giọt nước to như\nbóng. Phù hiệu vừa thức dậy mang tên 泣きます（なきます） —\nKhóc. Khi ngang qua ghế suy nghĩ, bộ não suy nghĩ tới mức phát ra\nkhói tím. Những nét mực tự sắp thành 考えます（かんがえます） —\nSuy nghĩ, cân nhắc; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực,\nAn thấy ở thùng trí nhớ cục tẩy xóa sạch tên khỏi bảng ghi nhớ.\nTiếng Nhật vang lên từ chính vật ấy: 忘れます（わすれます） —\nQuên.\n\n\nCàng đi sâu, những chữ viết trên tường càng giống tiếng nói của\nnhững người mà An từng quen. Còn tại đồng hồ trễ, đồng hồ báo\nmuộn réo như còi xe cứu hỏa. An thì thầm phù hiệu\n遅れます（おくれます） — Muộn, trễ, nghe nó hòa vào tiếng tim\nmình. Chạm vào ghế kiệt sức, An bỗng nhìn thấy người mệt nằm\nbẹp như tờ giấy. Dòng chữ 疲れます（つかれます） — Mệt, mệt mỏi\nhiện ra giữa không khí. Ở gối buồn ngủ, mắt buồn ngủ đóng sập dù\ncó chuông báo. Mực kêu lên một tiếng; trên nền nhà xuất hiện\n眠い（ねむい） — Buồn ngủ. Họ vừa đến túi chườm thì chiếc chân\nđau phải quấn băng thật to. An thử đọc phù hiệu 痛い（いたい） —\nĐau và cảnh tượng đứng yên.\n\n\nAn biết mình không thể quay lại đường cũ. Những dấu hiệu kế\ntiếp đang bày ra một lối thoát mới. Có tiếng răng rắc dưới con\nđường xa: con đường kéo dài vô tận qua núi rừng. Mực dùng đuôi\nvẽ lên bóng tối 遠い（とおい） — Xa. Tiến thêm một bước đến hàng\nrào nguy hiểm, An bắt gặp biển nguy hiểm đỏ rực dựng chắn trước\nmặt. Phù hiệu vừa thức dậy mang tên 危ない（あぶない） — Nguy\nhiểm. Khi ngang qua máy tạo gió cảm, con virus cảm lạnh hắt hơi\nra bão tuyết. Những nét mực tự sắp thành 風邪（かぜ） — Cảm, cảm\n\n\n\n\n                                87","lạnh; An lập tức ghi nhớ cảnh ấy. Không kịp gọi Mực, An thấy ở\nbảng lý do bảng lý do phun 100 dấu hỏi cùng lúc. Tiếng Nhật vang\nlên từ chính vật ấy: 理由（りゆう） — Lý do.\n\n\nTiếng bước chân của kẻ bí ẩn dồn lại phía sau. Hai người phải đi\ntiếp, dù thành phố chưa hết trò quái đản. Còn tại cổng lớp học, lớp\nhọc bay lên như tòa tháp tri thức. An thì thầm phù hiệu\n授業（じゅぎょう） — Buổi học, tiết học, nghe nó hòa vào tiếng tim\nmình.\n\n  An về đến lớp học cuối con đường. Trên bàn có một bức thư của\n  em gái: “Chị nhớ đường rồi. Giờ chúng ta có thể gặp nhau.”\n\n\n\n\n                                88","BẢN ĐỒ BỎ TÚI\n\n\n\n\nAtlas 26 tuyến ký ức\nMỗi chương là một tuyến đường. Khi câu chuyện còn trong\nđầu, những địa điểm sau đây sẽ dẫn trở lại từng cảnh đã\nđọc.\n\n\nBẢN ĐỒ CỦA NHỮNG CẢM GIÁC\n01. Cổng sắt bán cả bầu trời\nCổng sắt → Chuông cửa → Hòm thư → Lối lát gạch → Luống hoa → Thảm cỏ → Cây táo →\nGhế đá → Hòn non bộ → Cầu gỗ → Võng → Hồ cá → Đài phun nước → Chậu bonsai → Bàn\ntrà → Xích đu → Bậc thềm → Cửa hiên → Tượng đá\n\n02. Siêu thị của những chiếc nhãn biết cãi nhau\nCửa xoay → Bảng khuyến mãi → Quầy thông tin → Giỏ hàng → Cửa kính → Kệ gia vị → Kệ\nrau → Kệ hoa → Máy bán nước → Quầy bánh → Bàn ăn thử → Kệ đồ bếp → Quầy chăm sóc\n→ Quầy gương → Kệ sách → Kho hàng → Sàn lát gạch → Thang cuốn → Biển chỉ đường →\nTủ đông → Máy tính tiền → Băng chuyền → Túi mua sắm → Cửa ra\n\n03. Rạp chiếu phim nuốt mất màu sắc\nBiển tên rạp → Áp phích phim → Cửa bán vé → Hàng người chờ → Máy quét vé → Thảm\nđỏ → Tủ kính → Quầy bỏng ngô → Quầy nước → Cửa phòng chiếu → Hàng ghế đầu → Tay\nvịn → Trần rạp → Đèn chiếu → Màn chiếu → Màn nhung → Loa trái → Loa phải → Lối thoát\nhiểm → Cửa hậu trường → Tượng Oscar\n\n\n\nTHÀNH PHỐ KHÔNG NGỦ\n04. Ngày hôm qua chạy trốn\nCổng nhà → Móc chìa khóa → Bệ giày → Hành lang → Cửa bếp → Bát cơm → Ly nước →\nTivi → Tai nghe → Kệ sách → Bàn viết → Giường ngủ → Đồng hồ báo thức → Lịch treo →\nCửa sổ → Bàn ăn → Ấm trà → Thùng báo → Tủ sách → Cửa nhà tắm → Vòi sen → Tủ lạnh →\nBàn làm việc → Đèn ngủ\n\n\n\n\n                                        89","05. Cuộc thi tài năng của những người không có khả năng\nCổng sân khấu → Đèn neon → Mic đứng → Đàn piano → Hồ bơi giả → Vô lăng xe → Bếp\ndiễn → Bàn thủ công → Sân khấu trái → Sân khấu phải → Tai nghe → Bảng phiên dịch →\nBức tường Nhật → Bức tường Anh → Máy phát nhạc → Ghế nhạc công → Giá đàn guitar →\nSàn thể thao → Sân tennis → Đồi tuyết → Sàn nhảy\n\n06. Lớp học phép thuật và cây bút không trả\nCửa lớp → Chuông trường → Bàn giáo viên → Bảng phấn → Máy chiếu → Tủ mượn sách →\nChồng sách → Bàn học sinh → Tập vở → Bút máy → Hộp bút → Giá sách → Tủ trưng bày →\nCửa sổ trái → Cửa sổ phải → Đèn lớp → Quạt trần → Đồng hồ → Góc máy tính → Kệ cặp →\nNgăn kéo → Chậu cây → Bảng bài tập → Hòm thư → Cửa ra\n\n07. Trạm kiểm soát của người gác cổng vô hình\nCổng soát vé → Cửa ra vào → Ghế chờ → Bảng điện tử → Làn đỗ xe → Máy ảnh → Vạch\ncấm chạm → Thùng rác → Bảng cấm thuốc → Quầy nước → Bức ảnh → Máy photocopy →\nCặp hồ sơ → Tủ catalog → Đơn khai địa chỉ → Máy điện thoại → Bảng tên → Biển nguy\nhiểm → Tủ đồ quý → Quầy bảo vệ → Cửa kiểm tra\n\n08. Công viên mọc ra từ một tấm bưu thiếp\nCổng công viên → Quầy lưu trú → Bàn dọn đồ → Dây phơi → Sân tập → Đường đi bộ →\nQuầy mua sắm → Phòng triển lãm → Xe du lịch → Núi giả → Sông nhỏ → Bãi biển → Bãi cỏ\n→ Đền Thần đạo → Cổng chùa → Khách sạn mini → Bục đếm lần → Bảng số 0 → Đường\ntrở về → Hàng cây thay lá\n\n09. Ngã tư nơi thời tiết biết suy nghĩ\nỐng đo mưa → Máy đo tuyết → Cối xay gió → Mặt trời nhân tạo → Đám mây → Ghế suy\nnghĩ → Sổ tri thức → Album ký ức → Đường nhựa → Góc phố → Ngã tư → Đèn giao thông\n→ Mũi tên phải → Mũi tên trái → Khúc cua → Vạch qua đường → Cầu vượt → Bản đồ trời →\nBiển giả định → Bảng so sánh\n\n10. Bệnh viện chữa những vết thương của trí nhớ\nBảng ghi nhớ → Bàn đồ thất lạc → Ghế lo lắng → Cửa cấp cứu → Máy tập thể lực → Tủ\nthay đồ → Quầy thanh toán → Đồ dễ vỡ → Bồn rửa bẩn → Tủ thuốc → Nhiệt kế → Giường\nbệnh → Phòng khám → Quầy bảo hiểm → Móc áo khoác → Tủ đồ lót → Giá giày → Ngăn\ntất → Tủ đồ quý → Bảng nguy hiểm → Máy chờ lâu\n\n11. Nhà máy tăng ca tới ngày tận thế\nMáy chấm công → Bảng tăng ca → Vali công tác → Đồng hồ kịp giờ → Máy báo trễ → Van\ntròn → Cần kéo → Nút nhấn → Bảng đổi ca → Bản báo cáo → Phòng thi → Bảng đáp án →\nHộp câu hỏi → Biển giải nghĩa → Bảng Kanji → Hạn nộp → Chuông báo sớm → Biển tuyệt\nđối → Máy dự đoán → Cánh cửa chắc chắn\n\n\n\n\n                                        90","THẾ GIỚI CÓ HÌNH DÁNG\n12. Kho chứa những thứ có và không có\nCửa kho → Chuồng thú → Hòn đá → Cặp sách → Bàn gỗ → Ghế → Tivi cũ → Tủ lạnh → Cửa\nsổ → Bức tường → Sân sau → Thùng carton → Ổ mèo → Chuồng chó → Góc học → Bên\ncạnh tủ → Hộp bên trong → Sân bên ngoài → Giá cao → Ngăn thấp → Biển chỉ gần\n\n13. Chuyến tàu chạy xuyên qua bản đồ\nQuầy vé → Cổng gặp mặt → Bảng đổi tuyến → Bậc xuống tàu → Bảng tên ga → Cửa bách\nhóa → Quầy siêu thị → Cây ATM → Hòm thư bưu điện → Quầy cà phê → Đường ray tàu →\nLối tàu điện ngầm → Sân ga Shinkansen → Điểm xe buýt → Điểm taxi → Giá xe đạp → Nhà\nchờ sân bay → Bến thuyền → Lối đi bộ → Xe bánh mì → Quầy trà\n\n14. Bữa tối của hai mươi mốt vị khách\nẢnh gia đình → Ghế cha mẹ → Ghế bố → Ghế mẹ → Ghế anh trai → Ghế chị gái → Ghế em\ntrai → Ghế em gái → Ghế trẻ em → Chuông gọi người → Ghế bạn bè → Khay thịt → Đĩa bò\n→ Đĩa heo → Đĩa gà → Giỏ trứng → Rổ rau → Mâm trái cây → Bể cá → Bình nước → Đĩa\nbánh\n\n15. Tháp đồng hồ ăn mất thứ Hai\nMặt đồng hồ giờ → Kim phút → Đồng hồ cát → Bảng thứ Hai → Bảng thứ Ba → Bảng thứ\nTư → Bảng thứ Năm → Bảng thứ Sáu → Bảng thứ Bảy → Bảng Chủ Nhật → Ghế nghỉ →\nChuông nghỉ trưa → Lịch tháng → Lịch ngày → Sợi dây tuần → Cột mốc năm → Nửa bánh\n→ Ghế đơn → Ghế đôi → Tập giấy mỏng → Dãy máy móc\n\n16. Bưu điện gửi thư đến ngày mai\nHòm thư đến → Hòm thư đi → Cửa mở tiệc → Cửa kết thúc → Xe chở đồ → Bàn chuẩn bị →\nTập bài nhà → Hộp cơm → Bàn họp → Bàn tiệc → Bánh sinh nhật → Hộp quà → Quầy tem\n→ Bưu thiếp → Phong bì → Cửa chuyển phát nhanh → Máy bay chuyển thư → Tàu biển\nchuyển thư → Băng chuyền gửi → Núi hàng hóa\n\n\n\nCHIẾC CHÌA KHÓA LÀ MỘT CÂU HỎI\n17. Thám tử của mười hai câu hỏi\nGhế nghi phạm → Hộp bí ẩn → Cửa không tên → Đồng hồ kim → Bảng cách làm → Kệ đồ\nphân loại → Kính lúp lựa chọn → Hai cánh cửa → Máy tính tiền → Bình đếm → Thước đo →\nBảng nguyên nhân → Tủ nhiều ngăn → Tòa nhà mô hình → Giỏ ô → Tủ giày → Ví tiền →\nĐồng hồ đeo → Giá kính → Mũ thám tử → Cà vạt\n\n18. Ngôi chợ bán những thứ không ai nhìn thấy\nHộp gì đó → Bóng người → Bản đồ dấu X → Lịch mờ → Hộp trống → Ghế trống → Ngôi\nlàng vắng → Đồng hồ vô hạn → Cánh cổng dịch chuyển → Biển mọi người → Kệ vạn vật →\nCân hai phía → Quầy tìm kiếm → Kệ đồ vừa tìm → Quả địa cầu → Quốc kỳ → Cổng xuất\nngoại → Người ngoại quốc → Bảng ngôn ngữ → Cửa hàng → Quán cà phê\n\n\n\n\n                                        91","ĐIỀU MÌNH MUỐN GIỮ LẠI\n19. Tiệm quà nơi lòng tốt có hình dạng\nBàn tặng quà → Hộp quà nhận → Hòm thư yêu thương → Quầy cho mượn → Quầy đi\nmượn → Bàn chỉ dẫn → Bàn học thêm → Vali bưu kiện → Máy đếm tiền → Kệ tem → Giỏ\nhoa → Áo sơ mi → Khăn tay → Cà vạt → Hộp chocolate → Quầy quà lưu niệm → Tủ dụng\ncụ → Ghế cụ ông → Ghế cụ bà → Ghế chú bác → Ghế cô dì\n\n20. Hồ điều ước và đám cưới trên mây\nĐài phun điều ước → Cầu nguyện → Sân chơi → Ao câu cá → Cổng đám cưới → Bàn ăn →\nMáy nước khát → Tủ đồ đói → Ghế mỏi → Võng nghỉ → Giường lười → Gương giấc mơ →\nCỗ máy tương lai → Cổng cuối tuần → Bãi nghỉ hè → Bãi nghỉ đông → Đường đi đâu đó →\nHộp bí mật → Đồng hồ khoảng giờ → Sàn nằm dài\n\n21. Phòng khám của những lời hứa\nBiển nguyên nhân → Quầy xin lỗi → Phòng cảm cúm → Ghế ho → Máy đo đau đầu → Máy\nđo đau bụng → Nhiệt kế sốt → Băng cứu thương → Quầy chúc khỏe → Giường buồn ngủ\n→ Gánh nặng khổng lồ → Con đường gần → Con đường xa → Phòng nhỏ → Hội trường\nrộng → Cửa nguy hiểm → Bảng lý do → Bàn việc riêng → Sổ hẹn → Quầy làm thêm\n\n22. Phố mặt nạ và những tên gọi thân thương\nTủ áo → Kệ quần giày → Móc mũ → Gương kính → Ảnh em bé → Thước đo chiều cao →\nThước đo chiều thấp → Tròng mắt → Tai nghe → Mũi giả → Miệng cười → Hàm răng → Mái\ntóc giả → Gương mặt → Tượng cơ thể → Khách VIP → Thẻ cậu bé → Búp bê bé gái → Nhẫn\nđộc thân → Bảng tôi biết\n\n\n\nTIẾNG CHUÔNG CUỐI CÙNG\n23. Xưởng tranh giữ lại tiếng hát\nGiá vẽ → Đàn piano → Tủ sưu tầm → Bàn đổi đồ → Sổ ghi nhớ → Tẩy xóa ký ức → Bảng sở\nthích → Khung tranh → Dàn loa → Máy nhạc cổ điển → Đĩa jazz → Sân hòa nhạc → Mic\nkaraoke → Bài hát → Sàn nhảy → Nhật ký → Bộ thẻ → Máy internet → Cúp người giỏi →\nBảng người kém → Đồng hồ tốc độ\n\n24. Đài truyền hình phát toàn tin giả\nGhế bình luận → Micro phát biểu → Cúp chiến thắng → Bảng thua → Máy hữu ích → Bánh\nrăng chuyển động → Tivi thời sự → Bục chính trị → Bảng kinh tế → Sân thi đấu → Bảng ý\nkiến → Góc kể chuyện → Mặt nạ nói dối → Gương sự thật → Máy dự đoán → Máy chắc\nchắn → Thước mức độ → Bảng chủ đề → Ghế tất nhiên → Tấm lịch lâu ngày → Phong bì bí\nmật → Đèn spotlight → Cổng quay về → Cờ đích\n\n\n\n\n                                         92","25. Xưởng sửa chữa thành phố\nẢnh trẻ con → Sân chơi ngày xưa → Nhẫn thời độc thân → Ghế rảnh rỗi → Máy báo rắc rối\n→ Ghế cô đơn → Máy hỏng → Hộp dụng cụ sửa → Máy tra cứu → Cầu băng qua → Biển\ncảnh báo → Xe chuyển nhà → Kệ kích cỡ → Loa âm thanh → Cỗ máy cơ khí → Núm vặn →\nBộ phận hỏng → Đường trước xưởng → Ngã tư → Đèn tín hiệu\n\n26. Đường đua cuối cùng: không ai bị lãng quên\nVạch xuất phát → Làn chạy → Vô lăng → Sân hát → Mặt nạ cười → Mặt nạ khóc → Ghế suy\nnghĩ → Thùng trí nhớ → Đồng hồ trễ → Ghế kiệt sức → Gối buồn ngủ → Túi chườm → Con\nđường xa → Hàng rào nguy hiểm → Máy tạo gió cảm → Bảng lý do → Cổng lớp học\n\n\n\n\n                                         93","HẬU TRUYỆN\n\n\n\n\nLúc những tiếng chuông trở\nlại\nKhi An bước ra khỏi lớp học, cả thành phố đã lên đèn. Cánh cổng\ncao, siêu thị ồn ào, rạp phim đổi màu, nhà máy tăng ca, ga tàu, bữa\ncơm gia đình và tiệm quà — tất cả cùng vang lên như những âm\nthanh của đời sống.\n\nCô nhận ra Lão Rỗng không còn ở đó. Hắn nhỏ dần mỗi khi một\nđiều được gọi đúng tên, mỗi khi ai đó nói “tôi nhớ”, “tôi hiểu”, “tôi\nmuốn”, “tôi thích”, hay chỉ đơn giản gọi tên một người bạn.\n\nMực ngồi trên bậu cửa sổ, nhìn cuốn sổ đã kín chữ. “Cậu tưởng đó\nlà 545 cửa,” nó nói, “nhưng thật ra chúng là những chỗ để quay về.\nNgay cả khi quên một từ, cậu vẫn còn nhớ con đường dẫn đến nó.”\n\nAn gấp cuốn sổ. Ngoài cửa, trời vừa sáng. Một tiếng cười nhỏ vang\nlên, rồi có người gọi: “Chị ơi!” Cô quay lại. Lần này, gương mặt ấy\nkhông còn là khoảng trắng nữa.\n\nHết truyện. Thành phố vẫn ở đó, chờ những chuyến đi tiếp\ntheo.\n\n\n\n\n                                 94"]};
